// =====================================================================
// Juízes — tradução dos originais (versificação: Nova Vulgata)
// Formato: {s:"subtítulo"} abre trecho; {v,t,n} prosa; {v,l:[...]} verso;
// np:1 marca início de parágrafo.
// =====================================================================


window.TEXTOS_SEED["juizes"][1] = [
{s:"Judá e Simeão"},
{v:1,t:"Depois da morte de Josué, os filhos de Israel consultaram o Senhor, dizendo: Quem de nós subirá primeiro contra os cananeus, para lutar contra eles?",n:"O livro dos Juízes cobre o tempo entre a morte de Josué e o surgimento da monarquia, uns dois séculos. Os juízes não são magistrados, mas chefes carismáticos que Deus suscita para libertar uma ou outra tribo. O primeiro capítulo corrige a imagem de uma conquista total: registra, cidade por cidade, o que Israel não conseguiu tomar."},
{v:2,t:"O Senhor respondeu: Judá subirá; eis que entreguei a terra nas suas mãos."},
{v:3,t:"Judá disse a Simeão, seu irmão: Sobe comigo ao território que me coube, e lutaremos contra os cananeus; depois também eu irei contigo ao território que te coube. E Simeão foi com ele."},
{v:4,t:"Judá subiu, e o Senhor entregou-lhes nas mãos os cananeus e os ferezeus; e derrotaram em Bezec dez mil homens."},
{v:5,t:"Encontraram Adonibezec em Bezec, lutaram contra ele e derrotaram os cananeus e os ferezeus."},
{v:6,t:"Adonibezec fugiu, mas perseguiram-no, apanharam-no e cortaram-lhe os polegares das mãos e dos pés.",n:"Cortar os polegares inutilizava o guerreiro para a espada e para a corrida."},
{v:7,t:"Adonibezec disse: Setenta reis, com os polegares das mãos e dos pés cortados, apanhavam as migalhas debaixo da minha mesa. Como eu fiz, assim Deus me pagou. Levaram-no a Jerusalém, e ali morreu.",n:"O próprio pagão reconhece na sua sorte a justiça de Deus: é a pena de talião, olho por olho."},
{v:8,t:"Os filhos de Judá atacaram Jerusalém, tomaram-na, passaram-na ao fio da espada e incendiaram a cidade.",n:"O versículo 21 dirá que os jebuseus continuaram em Jerusalém, e só Davi a tomará de fato. Talvez se trate de uma incursão, ou da parte baixa da cidade."},
{v:9,t:"Depois os filhos de Judá desceram para lutar contra os cananeus que habitavam na montanha, no Negueb e na Sefelá."},
{v:10,t:"Judá marchou contra os cananeus que habitavam em Hebron, cujo nome era antes Cariat-Arbe, e derrotou Sesai, Aimã e Tolmai."},
{v:11,t:"Dali marchou contra os habitantes de Dabir, cujo nome era antes Cariat-Séfer, isto é, cidade das Letras.",np:1},
{v:12,t:"E Caleb disse: A quem atacar Cariat-Séfer e a tomar, darei minha filha Acsa por mulher."},
{v:13,t:"Otoniel, filho de Cenez, irmão mais novo de Caleb, tomou-a; e Caleb deu-lhe sua filha Acsa por mulher.",n:"O episódio é o mesmo contado em Josué 15, 15-19."},
{v:14,t:"Quando ela veio para junto dele, incitou-o a pedir um campo a seu pai. Ela desceu do jumento, e Caleb perguntou-lhe: Que desejas?"},
{v:15,t:"Ela respondeu: Dá-me um presente. Já que me deste uma terra seca, dá-me também fontes de água. E Caleb deu-lhe as fontes de cima e as fontes de baixo."},
{v:16,t:"Os filhos de Hobab, o quenita, parente de Moisés, subiram da cidade das Palmeiras com os filhos de Judá ao deserto de Judá, que está ao sul de Arad, e foram habitar com os amalecitas.",np:1,n:"Os quenitas, nômades ferreiros aparentados com Moisés, acompanharam Israel desde o deserto. A cidade das Palmeiras é Jericó. O hebraico diz habitaram com o povo; a Nova Vulgata, com a versão grega, lê com os amalecitas."},
{v:17,t:"Judá partiu com Simeão, seu irmão, e derrotaram os cananeus que habitavam em Sefat; votaram a cidade ao extermínio, e deram-lhe o nome de Horma.",n:"Horma soa como herem, o extermínio: quer dizer consagração ao anátema."},
{v:18,t:"Judá tomou também Gaza e o seu território, Ascalon e o seu território, e Acaron e o seu território.",n:"A versão grega diz que Judá não tomou estas cidades filisteias, o que concorda melhor com o versículo seguinte e com o resto da história; o hebraico e a Nova Vulgata dizem que as tomou."},
{v:19,t:"O Senhor estava com Judá, que se apoderou da montanha; mas não pôde expulsar os habitantes da planície, porque tinham carros de ferro."},
{v:20,t:"Deram Hebron a Caleb, como Moisés dissera; e ele expulsou dali os três filhos de Enac."},
{v:21,t:"Quanto aos jebuseus que habitavam em Jerusalém, os filhos de Benjamim não os expulsaram; e os jebuseus habitam com os filhos de Benjamim em Jerusalém até o dia de hoje.",n:"O livro de Josué dizia o mesmo dos filhos de Judá: Jerusalém ficava na fronteira das duas tribos."},
{s:"A casa de José e as outras tribos"},
{v:22,t:"Também a casa de José subiu contra Betel, e o Senhor estava com eles.",np:1},
{v:23,t:"Quando a casa de José mandou explorar Betel — cujo nome era antes Luza —,"},
{v:24,t:"os espiões viram um homem que saía da cidade e disseram-lhe: Mostra-nos por onde se entra na cidade, e usaremos de bondade contigo."},
{v:25,t:"Ele mostrou-lhes por onde se entrava na cidade, e eles a passaram ao fio da espada; mas deixaram ir aquele homem com toda a sua família."},
{v:26,t:"O homem foi para a terra dos heteus, construiu uma cidade e deu-lhe o nome de Luza; e esse é o seu nome até o dia de hoje.",n:"O homem de Luza repete ao contrário a história de Raab: ela escolheu Israel e ficou no meio do povo; ele salvou a vida e foi construir longe uma nova Luza."},
{v:27,t:"Manassés não expulsou os habitantes de Bet-San e das suas cidades dependentes, nem os de Tanac e das suas cidades dependentes, nem os de Dor e das suas cidades dependentes, nem os de Jeblaam e das suas cidades dependentes, nem os de Meguido e das suas cidades dependentes; os cananeus conseguiram continuar habitando nessa terra.",np:1},
{v:28,t:"Quando Israel se tornou mais forte, sujeitou os cananeus a trabalhos forçados, mas não os expulsou."},
{v:29,t:"Também Efraim não expulsou os cananeus que habitavam em Gazer; e os cananeus continuaram habitando no meio dele, em Gazer."},
{v:30,t:"Zabulon não expulsou os habitantes de Cetron nem os habitantes de Naalol; os cananeus habitaram no meio dele e foram sujeitos a trabalhos forçados."},
{v:31,t:"Aser não expulsou os habitantes de Aco, nem os de Sidônia, de Aalab, de Aczib, de Helba, de Afec e de Roob;"},
{v:32,t:"e os de Aser habitaram no meio dos cananeus, habitantes da terra, porque não os expulsaram."},
{v:33,t:"Neftali não expulsou os habitantes de Bet-Sames nem os de Bet-Anat, e habitou no meio dos cananeus, habitantes da terra; mas os habitantes de Bet-Sames e de Bet-Anat foram-lhe sujeitos a trabalhos forçados."},
{v:34,t:"Os amorreus repeliram os filhos de Dã para a montanha, e não os deixaram descer à planície.",n:"É a razão da migração de Dã para o norte, que o capítulo 18 vai contar."},
{v:35,t:"Os amorreus conseguiram continuar habitando em Har-Heres, em Aialon e em Salebim; mas a mão da casa de José pesou sobre eles, e foram sujeitos a trabalhos forçados."},
{v:36,t:"O território dos amorreus ia desde a subida de Acrabim até a Rocha, e mais acima."}
];

window.TEXTOS_SEED["juizes"][2] = [
{s:"O anjo do Senhor em Boquim"},
{v:1,t:"O anjo do Senhor subiu de Guilgal a Boquim e disse: Eu vos fiz subir do Egito e vos trouxe à terra que jurara dar a vossos pais; e disse: Nunca romperei a minha aliança convosco,",n:"O anjo do Senhor é, em muitas páginas antigas, o próprio Senhor que se torna visível e fala: aqui fala na primeira pessoa, em nome de Deus."},
{v:2,t:"com a condição de que não fizésseis aliança com os habitantes desta terra, mas derrubásseis os seus altares. Mas não obedecestes à minha voz. Por que fizestes isto?"},
{v:3,t:"Por isso também eu digo: Não os expulsarei de diante de vós; eles serão para vós um laço, e os seus deuses, uma armadilha."},
{v:4,t:"Quando o anjo do Senhor disse estas palavras a todos os filhos de Israel, o povo levantou a voz e chorou."},
{v:5,t:"E deram àquele lugar o nome de Boquim; e ofereceram ali sacrifícios ao Senhor.",n:"Boquim quer dizer os que choram."},
{s:"A geração que não conhecia o Senhor"},
{v:6,t:"Quando Josué despediu o povo, os filhos de Israel foram, cada um para a sua herança, para tomar posse da terra.",np:1,n:"Os versículos 6 a 9 retomam, quase à letra, o fim do livro de Josué: o livro dos Juízes começa pela segunda vez."},
{v:7,t:"O povo serviu o Senhor durante toda a vida de Josué e durante toda a vida dos anciãos que sobreviveram a Josué e que tinham visto toda a grande obra que o Senhor fizera por Israel."},
{v:8,t:"Josué, filho de Nun, servo do Senhor, morreu com a idade de cento e dez anos,"},
{v:9,t:"e sepultaram-no no território da sua herança, em Tamnat-Saré, na montanha de Efraim, ao norte do monte Gaás."},
{v:10,t:"Também toda aquela geração foi reunida a seus pais, e depois dela levantou-se outra geração, que não conhecia o Senhor, nem a obra que ele fizera por Israel.",n:"Conhecer, na Bíblia, é mais do que saber: é ter a experiência viva de alguém. A fé que não se transmite morre numa geração."},
{v:11,t:"Os filhos de Israel fizeram o que era mau aos olhos do Senhor e serviram os baais.",np:1,n:"Começa aqui o esquema que o livro vai repetir: Israel peca, Deus o entrega aos inimigos, Israel clama, Deus suscita um juiz que o liberta, a terra descansa — até o juiz morrer e tudo recomeçar. Os baais eram as figuras locais de Baal, deus cananeu da tempestade e da fertilidade."},
{v:12,t:"Abandonaram o Senhor, Deus de seus pais, que os fizera sair da terra do Egito, e seguiram outros deuses, dos deuses dos povos que os rodeavam; prostraram-se diante deles e irritaram o Senhor."},
{v:13,t:"Abandonaram o Senhor e serviram Baal e as Astartes.",n:"Astarte, ou Astarot, era a deusa cananeia do amor e da guerra, companheira de Baal."},
{v:14,t:"A ira do Senhor inflamou-se contra Israel, e ele os entregou nas mãos de saqueadores, que os saquearam; vendeu-os às mãos dos inimigos que os rodeavam, e eles não puderam mais resistir aos seus inimigos."},
{v:15,t:"Em tudo o que empreendiam, a mão do Senhor estava contra eles para o mal, como o Senhor dissera e como lhes jurara; e ficaram em grande aflição."},
{v:16,t:"Então o Senhor suscitou juízes, que os livraram das mãos dos que os saqueavam.",np:1},
{v:17,t:"Mas também não escutaram os seus juízes, porque se prostituíram com outros deuses e se prostraram diante deles. Desviaram-se depressa do caminho por onde tinham andado os seus pais, que obedeciam aos mandamentos do Senhor; não fizeram como eles.",n:"Prostituir-se é a imagem que os profetas usarão para a idolatria: a aliança é um casamento, e o culto a outros deuses, um adultério."},
{v:18,t:"Quando o Senhor lhes suscitava juízes, o Senhor estava com o juiz e os livrava das mãos dos seus inimigos durante toda a vida do juiz; pois o Senhor se compadecia dos seus gemidos por causa dos que os oprimiam e maltratavam.",n:"Compadecia-se: o verbo hebraico, nicham, diz também mudar de sentimento. Deus não é indiferente ao gemido dos oprimidos, mesmo quando a opressão é consequência do pecado."},
{v:19,t:"Mas, quando o juiz morria, voltavam a corromper-se mais do que os seus pais, seguindo outros deuses, servindo-os e prostrando-se diante deles; não renunciavam às suas práticas nem ao seu caminho obstinado."},
{v:20,t:"Por isso a ira do Senhor inflamou-se contra Israel, e ele disse: Porque esta nação transgrediu a aliança que eu prescrevi a seus pais e não escutou a minha voz,",np:1},
{v:21,t:"também eu não expulsarei mais de diante deles nenhuma das nações que Josué deixou quando morreu,"},
{v:22,t:"para por meio delas pôr Israel à prova, se guardam ou não o caminho do Senhor, andando nele como os seus pais o guardaram."},
{v:23,t:"Por isso o Senhor deixou ficar essas nações, sem as expulsar logo, e não as entregou nas mãos de Josué."}
];

window.TEXTOS_SEED["juizes"][3] = [
{s:"As nações que ficaram"},
{v:1,t:"Estas são as nações que o Senhor deixou ficar para por meio delas pôr à prova Israel, todos os que não tinham conhecido nenhuma das guerras de Canaã",n:"Três razões diferentes explicam, nos capítulos 2 e 3, a presença das nações: castigo, prova, aprendizado da guerra. O livro não escolhe entre elas."},
{v:2,t:"— somente para que as gerações dos filhos de Israel aprendessem a guerra, ao menos as que antes não a tinham conhecido —:"},
{v:3,t:"os cinco príncipes dos filisteus, todos os cananeus, os sidônios e os heveus que habitavam na montanha do Líbano, desde o monte de Baal-Hermon até a entrada de Emat."},
{v:4,t:"Elas ficaram para que por meio delas se pusesse Israel à prova, para saber se obedeceria aos mandamentos que o Senhor dera a seus pais por meio de Moisés."},
{v:5,t:"Assim, os filhos de Israel habitaram no meio dos cananeus, dos heteus, dos amorreus, dos ferezeus, dos heveus e dos jebuseus;",np:1},
{v:6,t:"tomaram as filhas deles por mulheres, deram as suas próprias filhas aos filhos deles e serviram os seus deuses."},
{s:"Otoniel"},
{v:7,t:"Os filhos de Israel fizeram o que era mau aos olhos do Senhor; esqueceram o Senhor seu Deus e serviram os baais e as aserás.",np:1,n:"As aserás eram postes sagrados de madeira, símbolos da deusa Aserá. A Nova Vulgata diz aqui Astarot."},
{v:8,t:"A ira do Senhor inflamou-se contra Israel, e ele os entregou nas mãos de Cusã-Rasataim, rei da Mesopotâmia; e os filhos de Israel serviram Cusã-Rasataim durante oito anos.",n:"Cusã-Rasataim quer dizer Cusã da dupla maldade: o nome parece ser uma deformação irônica. Mesopotâmia traduz Aram dos dois rios, no norte da Síria."},
{v:9,t:"Os filhos de Israel clamaram ao Senhor, e o Senhor suscitou-lhes um salvador, que os libertou: Otoniel, filho de Cenez, irmão mais novo de Caleb."},
{v:10,t:"O Espírito do Senhor veio sobre ele, e ele julgou Israel. Saiu para a guerra, e o Senhor entregou-lhe nas mãos Cusã-Rasataim, rei da Mesopotâmia; e a sua mão prevaleceu contra Cusã-Rasataim.",n:"O Espírito do Senhor, que virá sobre Gedeão, Jefté e Sansão, é a força de Deus que se apodera de um homem para uma missão. Otoniel é o juiz modelo, contado só com as fórmulas do esquema."},
{v:11,t:"A terra descansou quarenta anos, e Otoniel, filho de Cenez, morreu."},
{s:"Aod"},
{v:12,t:"Os filhos de Israel voltaram a fazer o que era mau aos olhos do Senhor; e o Senhor fortaleceu Eglon, rei de Moab, contra Israel, porque tinham feito o que era mau aos olhos do Senhor.",np:1},
{v:13,t:"Eglon aliou-se aos filhos de Amon e a Amalec, marchou, derrotou Israel e apoderou-se da cidade das Palmeiras."},
{v:14,t:"E os filhos de Israel serviram Eglon, rei de Moab, durante dezoito anos."},
{v:15,t:"Os filhos de Israel clamaram ao Senhor, e o Senhor suscitou-lhes um salvador: Aod, filho de Gera, benjaminita, que era canhoto. Os filhos de Israel enviaram por meio dele o tributo a Eglon, rei de Moab.",n:"Canhoto, à letra impedido da mão direita. Há ironia: Benjamim quer dizer filho da direita. Um guarda revistaria o lado esquerdo, onde um destro traz a espada."},
{v:16,t:"Aod fez para si um punhal de dois gumes, de um palmo de comprimento, e cingiu-o debaixo da roupa, sobre a coxa direita."},
{v:17,t:"E apresentou o tributo a Eglon, rei de Moab. Ora, Eglon era um homem muito gordo.",n:"Eglon soa como egel, bezerro: o rei gordo é o novilho cevado para o sacrifício. A narrativa, com os seus detalhes crus, é uma sátira do opressor."},
{v:18,t:"Depois de apresentar o tributo, despediu os homens que o tinham carregado;"},
{v:19,t:"mas ele mesmo voltou dos ídolos que estão perto de Guilgal e disse: Tenho uma palavra secreta para ti, ó rei. O rei disse: Silêncio! E saíram todos os que estavam junto dele.",n:"Os ídolos, pesilim, eram talvez estátuas de pedra junto de Guilgal, que serviam de marco."},
{v:20,t:"Aod aproximou-se dele, que estava sentado sozinho no quarto fresco do andar de cima, e disse: Tenho uma palavra de Deus para ti. O rei levantou-se do trono."},
{v:21,t:"Então Aod estendeu a mão esquerda, tirou o punhal da coxa direita e cravou-o no ventre do rei,"},
{v:22,t:"de tal modo que também o cabo entrou atrás da lâmina, e a gordura fechou-se sobre a lâmina; pois ele não tirou o punhal do ventre. E os excrementos saíram."},
{v:23,t:"Aod saiu pelo vestíbulo, fechou atrás de si as portas do quarto de cima e passou o ferrolho."},
{v:24,t:"Depois que ele saiu, chegaram os servos do rei e viram que as portas do quarto de cima estavam trancadas; e disseram: Certamente está fazendo as suas necessidades no quarto fresco.",n:"À letra, está cobrindo os pés, eufemismo hebraico. O cheiro confirmava a suposição dos servos, e a demora deu a Aod o tempo da fuga."},
{v:25,t:"Esperaram até ficarem constrangidos; e, como ele não abria as portas do quarto, tomaram a chave e abriram: o seu senhor estava caído no chão, morto."},
{v:26,t:"Enquanto eles hesitavam, Aod escapara; passou pelos ídolos e refugiou-se em Seira.",np:1},
{v:27,t:"Quando chegou, tocou a trombeta na montanha de Efraim, e os filhos de Israel desceram com ele da montanha; e ele ia à frente deles."},
{v:28,t:"E disse-lhes: Segui-me, porque o Senhor entregou nas vossas mãos os vossos inimigos, os moabitas. Desceram atrás dele, ocuparam os vaus do Jordão, na direção de Moab, e não deixaram passar ninguém."},
{v:29,t:"Naquele tempo, derrotaram os moabitas, uns dez mil homens, todos robustos e valentes; e nenhum escapou."},
{v:30,t:"Naquele dia, Moab foi humilhado sob a mão de Israel; e a terra descansou oitenta anos."},
{s:"Samgar"},
{v:31,t:"Depois dele veio Samgar, filho de Anat, que derrotou seiscentos filisteus com uma aguilhada de bois; também ele salvou Israel.",np:1,n:"Anat é o nome de uma deusa cananeia da guerra: Samgar talvez não fosse israelita. Os juízes que o livro menciona de passagem, sem história, costumam chamar-se juízes menores."}
];

window.TEXTOS_SEED["juizes"][4] = [
{s:"Débora e Barac"},
{v:1,t:"Depois da morte de Aod, os filhos de Israel voltaram a fazer o que era mau aos olhos do Senhor;"},
{v:2,t:"e o Senhor os entregou nas mãos de Jabin, rei de Canaã, que reinava em Hasor. O chefe do seu exército chamava-se Sísara e habitava em Haroset-Goim.",n:"Jabin, rei de Hasor, é também o nome do rei vencido por Josué no capítulo 11: as tradições não se ajustam com exatidão. Haroset-Goim quer dizer Haroset das nações."},
{v:3,t:"Os filhos de Israel clamaram ao Senhor, porque Jabin tinha novecentos carros de ferro e oprimira duramente os filhos de Israel durante vinte anos."},
{v:4,t:"Naquele tempo, Débora, uma profetisa, mulher de Lapidot, julgava Israel.",np:1,n:"Débora quer dizer abelha. É a única juíza de Israel e a primeira profetisa depois de Míriam: exerce ao mesmo tempo a justiça e a palavra de Deus."},
{v:5,t:"Ela se sentava debaixo da palmeira de Débora, entre Ramá e Betel, na montanha de Efraim; e os filhos de Israel subiam a ela para os julgamentos."},
{v:6,t:"Ela mandou chamar Barac, filho de Abinoem, de Cedes de Neftali, e disse-lhe: O Senhor, Deus de Israel, te ordena: Vai, reúne gente no monte Tabor e toma contigo dez mil homens dos filhos de Neftali e dos filhos de Zabulon."},
{v:7,t:"Eu atrairei para ti, à torrente de Quison, Sísara, chefe do exército de Jabin, com os seus carros e a sua multidão, e o entregarei nas tuas mãos."},
{v:8,t:"Barac respondeu-lhe: Se vieres comigo, irei; mas, se não vieres comigo, não irei."},
{v:9,t:"Ela disse: Irei contigo, certamente; mas não será tua a glória no caminho que vais seguir, porque o Senhor entregará Sísara nas mãos de uma mulher. Débora levantou-se e foi com Barac a Cedes.",n:"O leitor pensa em Débora; a mulher será outra, Jael."},
{v:10,t:"Barac convocou Zabulon e Neftali a Cedes; dez mil homens subiram atrás dele, e Débora subiu com ele."},
{v:11,t:"Héber, o quenita, tinha-se separado dos quenitas, descendentes de Hobab, parente de Moisés, e armara a sua tenda junto ao carvalho de Saananim, perto de Cedes.",np:1},
{v:12,t:"Anunciaram a Sísara que Barac, filho de Abinoem, tinha subido ao monte Tabor."},
{v:13,t:"Sísara reuniu todos os seus carros, novecentos carros de ferro, e todo o povo que estava com ele, desde Haroset-Goim até a torrente de Quison."},
{v:14,t:"Débora disse a Barac: Levanta-te, porque este é o dia em que o Senhor entregou Sísara nas tuas mãos. Não é o Senhor que sai à tua frente? Barac desceu do monte Tabor, e dez mil homens atrás dele.",np:1},
{v:15,t:"O Senhor lançou o pânico em Sísara, em todos os seus carros e em todo o seu exército, diante de Barac, ao fio da espada; e Sísara desceu do carro e fugiu a pé.",n:"O cântico do capítulo 5 dirá como: a torrente de Quison transbordou, e os carros atolaram na lama. A arma temida tornou-se inútil."},
{v:16,t:"Barac perseguiu os carros e o exército até Haroset-Goim, e todo o exército de Sísara caiu ao fio da espada; não ficou nenhum."},
{v:17,t:"Sísara fugiu a pé para a tenda de Jael, mulher de Héber, o quenita, porque havia paz entre Jabin, rei de Hasor, e a casa de Héber, o quenita.",np:1},
{v:18,t:"Jael saiu ao encontro de Sísara e disse-lhe: Entra, meu senhor, entra aqui; não tenhas medo. Ele entrou na tenda dela, e ela o cobriu com um manto."},
{v:19,t:"Ele lhe disse: Dá-me, por favor, um pouco de água para beber, porque tenho sede. Ela abriu o odre de leite, deu-lhe de beber e o cobriu."},
{v:20,t:"Ele lhe disse: Fica à entrada da tenda; e, se alguém vier e te perguntar: Há alguém aqui?, responde: Não."},
{v:21,t:"Mas Jael, mulher de Héber, tomou uma estaca da tenda, pegou o martelo, aproximou-se dele devagar e cravou-lhe a estaca na têmpora, até pregá-la no chão; ele estava profundamente adormecido, esgotado, e morreu.",n:"Nota do tradutor: o gesto de Jael viola a lei sagrada da hospitalidade, e o texto não o esconde. O livro celebra-o como libertação de um povo oprimido, e o cântico do capítulo seguinte chama-a bendita entre as mulheres. A Escritura narra a violência de uma época sem a propor como modelo; a própria fé de Israel, e mais ainda o Evangelho, ensinarão a não pagar o mal com o mal. Armar e desarmar a tenda era trabalho das mulheres: Jael usa as ferramentas que conhecia."},
{v:22,t:"E eis que Barac, que perseguia Sísara, chegou. Jael saiu ao seu encontro e disse-lhe: Vem, que eu te mostrarei o homem que procuras. Ele entrou com ela: Sísara jazia morto, com a estaca na têmpora.",np:1},
{v:23,t:"Assim, naquele dia, Deus humilhou Jabin, rei de Canaã, diante dos filhos de Israel;"},
{v:24,t:"e a mão dos filhos de Israel foi pesando cada vez mais sobre Jabin, rei de Canaã, até que o exterminaram."}
];

window.TEXTOS_SEED["juizes"][5] = [
{s:"O cântico de Débora"},
{v:1,t:"Naquele dia, Débora e Barac, filho de Abinoem, cantaram este cântico:",n:"O cântico de Débora é tido por um dos textos mais antigos da Bíblia, talvez do século XII antes de Cristo, próximo dos fatos que canta. O hebraico é arcaico e em muitos versos obscuro; a tradução segue o sentido mais provável e, onde o texto é incerto, a leitura da Nova Vulgata."},
{v:2,l:["Quando em Israel os guerreiros soltam a cabeleira,","quando o povo se oferece de boa vontade,","bendizei o Senhor!"],n:"Soltar a cabeleira: talvez o voto dos guerreiros consagrados à guerra santa, que não cortavam o cabelo, como Sansão. Outros entendem: quando os chefes tomam a frente."},
{v:3,l:["Ouvi, reis; escutai, príncipes:","eu, eu cantarei ao Senhor,","salmodiarei ao Senhor, Deus de Israel!"]},
{v:4,l:["Senhor, quando saíste de Seir,","quando avançaste dos campos de Edom,","a terra tremeu, os céus gotejaram, e as nuvens desfizeram-se em água;"],n:"O Senhor vem do sul, de Seir e de Edom, onde fica o Sinai: a teofania do Sinai repete-se na tempestade que decide a batalha."},
{v:5,l:["os montes derreteram-se diante do Senhor, o do Sinai,","diante do Senhor, Deus de Israel."]},
{v:6,l:["Nos dias de Samgar, filho de Anat,","nos dias de Jael, os caminhos estavam desertos, e os viajantes","seguiam por atalhos tortuosos."]},
{v:7,l:["Faltaram os chefes em Israel, faltaram,","até que te levantaste, Débora,","te levantaste como mãe em Israel."]},
{v:8,l:["Escolheram deuses novos;","então a guerra estava às portas.","Não se via escudo nem lança","entre quarenta mil em Israel."],n:"Os versos 8 a 11 estão entre os mais obscuros do texto hebraico."},
{v:9,l:["O meu coração está com os chefes de Israel.","Vós, que vos oferecestes de boa vontade no meio do povo, bendizei o Senhor!"]},
{v:10,l:["Vós, que montais em jumentas brancas","e vos sentais sobre tapetes,","e vós, que andais pelo caminho, falai!"]},
{v:11,l:["Ao som dos que repartem as águas","junto aos bebedouros,","ali se celebram os atos de justiça do Senhor,","os atos de justiça do seu poder em Israel.","Então o povo do Senhor desceu às portas."]},
{v:12,l:["Desperta, desperta, Débora;","desperta, desperta, entoa um cântico!","Levanta-te, Barac, e leva os teus cativos,","filho de Abinoem!"]},
{v:13,l:["Então o resto desceu ao encontro dos nobres,","o povo do Senhor desceu com ele entre os valentes."]},
{v:14,l:["De Efraim vieram os chefes para o vale,","atrás de ti, Benjamim, entre as tuas tropas.","De Maquir desceram os comandantes, e de Zabulon os que empunham o bastão de chefe."],n:"O cântico passa em revista as tribos: umas vieram — Efraim, Benjamim, Maquir, Zabulon, Issacar, Neftali —, outras ficaram em casa — Rúben, Galaad, Dã, Aser. Judá e Simeão nem são nomeados: Israel ainda não é um povo unido."},
{v:15,l:["Os príncipes de Issacar estavam com Débora,","e Barac foi lançado ao vale com os seus soldados a pé.","Entre os clãs de Rúben, grandes deliberações do coração."]},
{v:16,l:["Por que ficaste sentado entre os currais,","para ouvir a flauta junto dos rebanhos?","Entre os clãs de Rúben, grandes indecisões do coração."],n:"Ironia amarga: Rúben muito deliberou e nada fez."},
{v:17,l:["Galaad ficou do outro lado do Jordão;","e Dã, por que se demora junto aos navios?","Aser ficou na costa do mar","e permaneceu nos seus portos."]},
{v:18,l:["Mas Zabulon é um povo que expôs a vida à morte,","e Neftali, nas alturas do campo."]},
{v:19,l:["Vieram os reis e combateram,","combateram então os reis de Canaã,","em Tanac, junto às águas de Meguido; mas não levaram despojo de prata!"]},
{v:20,l:["Do céu combateram as estrelas,","das suas órbitas combateram contra Sísara."],n:"As estrelas eram imaginadas como o exército do céu. A chuva torrencial que fez transbordar o Quison é cantada como o céu inteiro em guerra por Israel."},
{v:21,l:["A torrente de Quison arrastou-os,","a torrente antiga, a torrente de Quison. Avança, ó minha alma, com força!"]},
{v:22,l:["Então ressoaram os cascos dos cavalos","no galope, no galope dos seus corcéis."]},
{v:23,l:["Amaldiçoai Meroz, diz o anjo do Senhor,","amaldiçoai, amaldiçoai os seus habitantes,","porque não vieram em socorro do Senhor,","em socorro do Senhor entre os valentes."]},
{v:24,l:["Bendita entre as mulheres seja Jael, mulher de Héber, o quenita,","entre as mulheres da tenda seja bendita!"],n:"Bendita entre as mulheres: a mesma saudação que Isabel dirigirá a Maria, no Evangelho segundo São Lucas. Os Padres viram em Jael, que esmaga a cabeça do inimigo, uma figura da mulher do Gênesis e de Maria."},
{v:25,l:["Ele pediu água, ela deu-lhe leite;","numa taça de príncipes ofereceu-lhe coalhada."]},
{v:26,l:["Estendeu a mão esquerda para a estaca,","e a direita para o martelo dos trabalhadores;","feriu Sísara, esmagou-lhe a cabeça,","furou e traspassou-lhe a têmpora."]},
{v:27,l:["Aos pés dela ele se curvou, caiu, ficou estendido;","aos pés dela se curvou e caiu;","onde se curvou, ali caiu, sem vida."]},
{v:28,l:["Pela janela olha e lamenta","a mãe de Sísara, através da grade:","Por que tarda a chegar o seu carro? Por que se atrasam as rodas dos seus carros?"],n:"A cena passa de repente à mãe do vencido, que espera à janela. O poeta não sente pena dela, mas a sua ironia deixa entrever o outro lado da guerra."},
{v:29,l:["As mais sábias das suas damas respondem-lhe,","e ela mesma repete para si as suas palavras:"]},
{v:30,l:["Certamente estão repartindo os despojos que acharam: uma moça, duas moças para cada guerreiro;","um despojo de tecidos coloridos","para Sísara;","um ou dois bordados de cores","para o meu pescoço, como despojo."]},
{v:31,l:["Assim pereçam todos os teus inimigos, Senhor!","Mas os que o amam sejam","como o sol quando se levanta em todo o seu esplendor."],n:"A Nova Vulgata divide em dois versículos, 31 e 32, o que o hebraico conta como um só; por isso o capítulo tem aqui um versículo a mais."},
{v:32,t:"E a terra descansou quarenta anos.",np:1}
];

window.TEXTOS_SEED["juizes"][6] = [
{s:"A opressão de Madiã"},
{v:1,t:"Os filhos de Israel fizeram o que era mau aos olhos do Senhor, e o Senhor os entregou nas mãos de Madiã durante sete anos."},
{v:2,t:"A mão de Madiã pesou sobre Israel; por causa de Madiã, os filhos de Israel fizeram para si os esconderijos que há nas montanhas, as cavernas e os lugares fortificados."},
{v:3,t:"Sempre que Israel semeava, subiam Madiã, Amalec e os filhos do Oriente, e subiam contra ele;",n:"Os madianitas, nômades do deserto a leste, fazem incursões no tempo da colheita. É a primeira vez que a Bíblia mostra camelos usados em grande número na guerra."},
{v:4,t:"acampavam diante deles, destruíam os produtos da terra até a entrada de Gaza e não deixavam em Israel nada que desse sustento, nem ovelha, nem boi, nem jumento."},
{v:5,t:"Pois subiam com os seus rebanhos e as suas tendas, e chegavam numerosos como gafanhotos; eles e os seus camelos eram inumeráveis, e invadiam a terra para devastá-la."},
{v:6,t:"Israel ficou muito empobrecido por causa de Madiã."},
{v:7,t:"E clamou ao Senhor, pedindo socorro contra os madianitas."},
{v:8,t:"O Senhor enviou-lhes um profeta, que lhes disse: Assim diz o Senhor, Deus de Israel: Eu vos fiz subir do Egito e vos tirei da casa da escravidão;",np:1},
{v:9,t:"livrei-vos das mãos dos egípcios e das mãos de todos os que vos oprimiam; expulsei-os de diante de vós e vos dei a terra deles."},
{v:10,t:"E disse-vos: Eu sou o Senhor vosso Deus; não temais os deuses dos amorreus, em cuja terra habitais. Mas não escutastes a minha voz.",n:"O profeta sem nome faz, antes do libertador, o diagnóstico: o problema de Israel não é Madiã; é a infidelidade."},
{s:"O chamado de Gedeão"},
{v:11,t:"O anjo do Senhor veio e sentou-se debaixo do carvalho de Efra, que pertencia a Joás, do clã de Abiezer. Gedeão, seu filho, malhava o trigo no lagar, para escondê-lo de Madiã.",np:1,n:"Malhar o trigo no lagar, uma cavidade escavada na rocha, e não na eira aberta ao vento, era o modo de escondê-lo dos saqueadores. O libertador é chamado enquanto se esconde."},
{v:12,t:"O anjo do Senhor apareceu-lhe e disse: O Senhor está contigo, valente guerreiro!",n:"O Senhor está contigo: é a saudação que o anjo dirá a Maria. Valente guerreiro, a um homem que se escondia: Deus chama alguém por aquilo que vai fazer dele."},
{v:13,t:"Gedeão respondeu: Ah, meu senhor! Se o Senhor está conosco, por que nos aconteceu tudo isto? Onde estão todas as suas maravilhas, que os nossos pais nos contaram, dizendo: O Senhor nos fez subir do Egito? Agora o Senhor nos abandonou e nos entregou nas mãos de Madiã."},
{v:14,t:"O Senhor voltou-se para ele e disse: Vai com essa força que tens e livra Israel das mãos de Madiã. Não sou eu que te envio?"},
{v:15,t:"Ele respondeu: Ah, meu Senhor! Com que livrarei Israel? O meu clã é o mais fraco de Manassés, e eu sou o menor na casa de meu pai.",n:"O menor, o mais fraco: como Moisés, Saul, Davi e Jeremias, Gedeão alega a sua pequenez, e é por ela que Deus o escolhe."},
{v:16,t:"O Senhor disse-lhe: Eu estarei contigo, e derrotarás Madiã como se fosse um só homem."},
{v:17,t:"Ele disse: Se encontrei graça aos teus olhos, dá-me um sinal de que és tu que falas comigo."},
{v:18,t:"Não te retires daqui, peço-te, até que eu volte a ti, trazendo a minha oferta e colocando-a diante de ti. Ele respondeu: Ficarei aqui até que voltes."},
{v:19,t:"Gedeão entrou em casa, preparou um cabrito e, com um efá de farinha, pães sem fermento; pôs a carne num cesto e o caldo numa panela, trouxe-os para debaixo do carvalho e os apresentou.",np:1,n:"Um efá eram perto de vinte e dois litros: uma quantidade generosa, num tempo de fome."},
{v:20,t:"O anjo de Deus disse-lhe: Toma a carne e os pães sem fermento, põe-nos sobre esta rocha e derrama o caldo. Ele assim fez."},
{v:21,t:"O anjo do Senhor estendeu a ponta do cajado que tinha na mão e tocou a carne e os pães sem fermento; subiu da rocha um fogo que consumiu a carne e os pães. E o anjo do Senhor desapareceu dos seus olhos."},
{v:22,t:"Gedeão viu que era o anjo do Senhor e disse: Ai de mim, Senhor Deus, porque vi o anjo do Senhor face a face!",n:"Ninguém pode ver Deus e continuar vivo, dizia o Êxodo: daí o medo de Gedeão."},
{v:23,t:"O Senhor disse-lhe: A paz esteja contigo! Não temas; não morrerás."},
{v:24,t:"Gedeão construiu ali um altar ao Senhor e chamou-o: O Senhor é paz. Ele está ainda hoje em Efra dos abiezritas.",n:"O Senhor é paz, em hebraico Yahweh shalom."},
{s:"Gedeão derruba o altar de Baal"},
{v:25,t:"Naquela noite, o Senhor disse-lhe: Toma o touro de teu pai, o segundo touro, de sete anos; derruba o altar de Baal que pertence a teu pai e corta o poste sagrado que está junto dele;",np:1,n:"A primeira missão de Gedeão é dentro da própria casa: o pai tinha um altar a Baal. A reforma começa em casa."},
{v:26,t:"e constrói ao Senhor teu Deus, no alto desta fortaleza, um altar bem-disposto; depois toma o segundo touro e oferece-o em holocausto, com a lenha do poste sagrado que tiveres cortado."},
{v:27,t:"Gedeão tomou dez homens dentre os seus servos e fez como o Senhor lhe dissera; mas, como tinha medo da família de seu pai e dos homens da cidade, fê-lo de noite, e não de dia."},
{v:28,t:"Quando os homens da cidade se levantaram de manhã, viram que o altar de Baal tinha sido derrubado, o poste sagrado que estava junto dele cortado, e o segundo touro oferecido sobre o altar que fora construído."},
{v:29,t:"Perguntaram uns aos outros: Quem fez isto? Informaram-se e procuraram, e disseram: Foi Gedeão, filho de Joás, quem fez isto."},
{v:30,t:"Os homens da cidade disseram a Joás: Traze para fora o teu filho, para que morra, porque derrubou o altar de Baal e cortou o poste sagrado que estava junto dele."},
{v:31,t:"Joás respondeu a todos os que o cercavam: Quereis vós defender a causa de Baal? Quereis vós salvá-lo? Quem defender a causa dele será morto antes de amanhecer. Se ele é deus, que defenda ele mesmo a sua causa, já que derrubaram o seu altar.",n:"O argumento de Joás é o dos profetas: um deus que precisa ser defendido pelos homens não é Deus."},
{v:32,t:"Naquele dia, Gedeão recebeu o nome de Jerobaal, porque disseram: Que Baal dispute com ele, pois derrubou o seu altar.",n:"Jerobaal quer dizer que Baal dispute. O nome, que parecia honrar Baal, é relido como desafio ao ídolo."},
{s:"O sinal do velo"},
{v:33,t:"Todo o Madiã, Amalec e os filhos do Oriente reuniram-se, atravessaram o Jordão e acamparam no vale de Jezrael.",np:1},
{v:34,t:"O Espírito do Senhor revestiu Gedeão; ele tocou a trombeta, e os abiezritas foram convocados para segui-lo.",n:"Revestiu, à letra vestiu-se de Gedeão: o Espírito entra nele como numa roupa."},
{v:35,t:"Enviou mensageiros por todo o Manassés, que também o seguiu; e enviou mensageiros a Aser, a Zabulon e a Neftali, que subiram ao seu encontro."},
{v:36,t:"Gedeão disse a Deus: Se vais salvar Israel pela minha mão, como disseste,",np:1},
{v:37,t:"eis que vou pôr um velo de lã na eira: se houver orvalho só no velo, e todo o chão ficar seco, saberei que salvarás Israel pela minha mão, como disseste."},
{v:38,t:"E assim aconteceu. Levantou-se de madrugada, espremeu o velo e tirou dele orvalho, uma taça cheia de água."},
{v:39,t:"Gedeão disse ainda a Deus: Não se inflame contra mim a tua ira, se falar ainda uma vez; deixa-me fazer só mais uma prova com o velo: que fique seco só o velo, e haja orvalho em todo o chão."},
{v:40,t:"E Deus assim fez naquela noite: só o velo ficou seco, e houve orvalho em todo o chão.",n:"Pedir sinais a Deus não é caminho recomendado pela Escritura, e Gedeão pede dois, com medo de irritá-lo; Deus tem paciência com a sua fraqueza. Os Padres viram no velo orvalhado uma figura de Maria, que recebeu em si o orvalho do céu."}
];

window.TEXTOS_SEED["juizes"][7] = [
{s:"Os trezentos homens"},
{v:1,t:"Jerobaal, isto é, Gedeão, levantou-se de madrugada, com todo o povo que estava com ele, e acamparam junto à fonte de Harod; o acampamento de Madiã ficava ao norte dele, no vale, junto à colina de Moré.",n:"Harod quer dizer tremor: o nome prepara a triagem dos medrosos."},
{v:2,t:"O Senhor disse a Gedeão: O povo que está contigo é numeroso demais para que eu entregue Madiã nas suas mãos; Israel poderia gloriar-se contra mim, dizendo: A minha mão me salvou.",n:"Toda a história é uma lição sobre isto: a vitória vem de Deus, e não do número. São Paulo dirá que Deus escolhe o que é fraco para confundir o que é forte."},
{v:3,t:"Anuncia, pois, aos ouvidos do povo: Quem tiver medo e tremer, volte e retire-se do monte Gelboé. Voltaram vinte e dois mil homens do povo, e ficaram dez mil.",n:"O hebraico diz aqui monte Galaad, que fica do outro lado do Jordão; a Nova Vulgata lê Gelboé, que fica perto. A dispensa dos medrosos era lei da guerra santa, segundo o Deuteronômio."},
{v:4,t:"O Senhor disse a Gedeão: O povo ainda é numeroso demais. Faze-os descer à água, e ali os porei à prova para ti. Aquele de quem eu te disser: Este irá contigo, esse irá contigo; e todo aquele de quem eu te disser: Este não irá contigo, esse não irá.",np:1},
{v:5,t:"Gedeão fez o povo descer à água, e o Senhor disse-lhe: Todos os que lamberem a água com a língua, como lambe o cão, põe-nos de um lado; e todos os que se ajoelharem para beber, põe-nos do outro."},
{v:6,t:"O número dos que lamberam a água, levando-a à boca com a mão, foi de trezentos homens; todo o resto do povo se ajoelhou para beber.",n:"Não está claro o que o teste revela: talvez os que bebem levando a água com a mão fiquem atentos ao inimigo. O mais provável é que a escolha seja de propósito arbitrária: o que importa é que fiquem poucos."},
{v:7,t:"O Senhor disse a Gedeão: Com os trezentos homens que lamberam a água vos salvarei e entregarei Madiã nas tuas mãos; que todo o resto do povo volte, cada um para o seu lugar."},
{v:8,t:"Tomaram as provisões do povo e as suas trombetas, e Gedeão mandou todos os homens de Israel para as suas tendas, ficando só com os trezentos. O acampamento de Madiã estava abaixo dele, no vale."},
{s:"O sonho do pão de cevada"},
{v:9,t:"Naquela mesma noite, o Senhor disse-lhe: Levanta-te, desce contra o acampamento, porque o entreguei nas tuas mãos.",np:1},
{v:10,t:"Mas, se tens medo de descer, desce ao acampamento com Fara, teu servo;"},
{v:11,t:"ouvirás o que eles dizem, e depois as tuas mãos se fortalecerão, e descerás contra o acampamento. Ele desceu, pois, com Fara, seu servo, até a extremidade dos postos avançados do acampamento."},
{v:12,t:"Madiã, Amalec e todos os filhos do Oriente estavam estendidos no vale, numerosos como gafanhotos; os seus camelos eram inumeráveis, como a areia da praia do mar."},
{v:13,t:"Quando Gedeão chegou, um homem contava um sonho ao seu companheiro, dizendo: Tive um sonho: um pão de cevada rolava pelo acampamento de Madiã; chegou até a tenda, bateu nela, e ela caiu; revirou-a de cima para baixo, e a tenda ficou por terra.",n:"O pão de cevada, alimento dos pobres e dos agricultores, é Israel; a tenda é Madiã, o povo nômade."},
{v:14,t:"O companheiro respondeu: Isto não é outra coisa senão a espada de Gedeão, filho de Joás, homem de Israel; Deus entregou-lhe nas mãos Madiã e todo o acampamento."},
{v:15,t:"Quando Gedeão ouviu o relato do sonho e a sua interpretação, prostrou-se em adoração; voltou ao acampamento de Israel e disse: Levantai-vos, porque o Senhor entregou nas vossas mãos o acampamento de Madiã.",np:1},
{s:"A vitória sobre Madiã"},
{v:16,t:"Dividiu os trezentos homens em três grupos e deu-lhes a todos trombetas e cântaros vazios, com tochas dentro dos cântaros,",np:1},
{v:17,t:"e disse-lhes: Olhai para mim e fazei como eu. Quando eu chegar à extremidade do acampamento, fazei o que eu fizer."},
{v:18,t:"Quando eu e todos os que estão comigo tocarmos a trombeta, tocai também vós as trombetas em redor de todo o acampamento e gritai: Pelo Senhor e por Gedeão!"},
{v:19,t:"Gedeão e os cem homens que estavam com ele chegaram à extremidade do acampamento no começo da vigília do meio da noite, logo depois de rendidas as sentinelas; tocaram as trombetas e quebraram os cântaros que tinham nas mãos.",n:"O hebraico diz cem, um dos três grupos; a Nova Vulgata, com a Vulgata antiga, diz trezentos."},
{v:20,t:"Os três grupos tocaram as trombetas e quebraram os cântaros; com a mão esquerda seguravam as tochas, e com a direita as trombetas para tocar, e gritavam: Espada pelo Senhor e por Gedeão!"},
{v:21,t:"Ficaram cada um no seu lugar, em redor do acampamento; e todo o acampamento se pôs a correr, gritando e fugindo.",n:"Os trezentos não combatem: ficam no seu lugar. O barulho, as luzes e o pânico noturno fazem o resto."},
{v:22,t:"Enquanto os trezentos tocavam as trombetas, o Senhor fez que a espada de cada um se voltasse contra o companheiro, em todo o acampamento; e o exército fugiu até Bet-Seta, na direção de Sereda, até a margem de Abel-Meula, perto de Tebat."},
{v:23,t:"Os homens de Israel, de Neftali, de Aser e de todo o Manassés, foram convocados e perseguiram Madiã.",np:1},
{v:24,t:"Gedeão enviou mensageiros por toda a montanha de Efraim, dizendo: Descei ao encontro de Madiã e ocupai antes deles as águas até Bet-Bera, e o Jordão. Todos os homens de Efraim foram convocados e ocuparam as águas até Bet-Bera, e o Jordão."},
{v:25,t:"Capturaram os dois chefes de Madiã, Oreb e Zeb; mataram Oreb no rochedo de Oreb, e Zeb no lagar de Zeb; perseguiram Madiã e levaram a Gedeão, do outro lado do Jordão, as cabeças de Oreb e de Zeb.",n:"Oreb quer dizer corvo, e Zeb, lobo. Isaías lembrará o dia de Madiã como o grande exemplo da vitória de Deus."}
];

window.TEXTOS_SEED["juizes"][8] = [
{s:"Efraim, Sucot e Fanuel"},
{v:1,t:"Os homens de Efraim disseram a Gedeão: Que é isto que nos fizeste, não nos chamando quando foste combater Madiã? E discutiram violentamente com ele."},
{v:2,t:"Ele respondeu-lhes: Que fiz eu agora em comparação convosco? Não vale mais o rebusco de Efraim do que a vindima de Abiezer?",n:"O rebusco, os cachos que ficam depois da colheita, vale mais que a vindima inteira: Gedeão acalma o orgulho de Efraim com um provérbio e um elogio. A resposta branda desvia o furor, dirão os Provérbios."},
{v:3,t:"Deus entregou nas vossas mãos os chefes de Madiã, Oreb e Zeb. Que pude eu fazer em comparação convosco? Quando ele disse isto, o ânimo deles contra ele acalmou-se."},
{v:4,t:"Gedeão chegou ao Jordão e atravessou-o com os trezentos homens que o acompanhavam, cansados, mas continuando a perseguição.",np:1},
{v:5,t:"E disse aos homens de Sucot: Dai, por favor, pães ao povo que me segue, porque estão exaustos, e eu persigo Zebá e Salmana, reis de Madiã."},
{v:6,t:"Os chefes de Sucot responderam: Porventura já tens nas mãos as palmas das mãos de Zebá e Salmana, para que demos pão ao teu exército?",n:"Cortavam-se as mãos dos inimigos mortos para contá-los. Os de Sucot não querem comprometer-se antes de saber quem vence."},
{v:7,t:"Gedeão respondeu: Pois bem: quando o Senhor entregar nas minhas mãos Zebá e Salmana, malharei a vossa carne com os espinhos e os cardos do deserto."},
{v:8,t:"Dali subiu a Fanuel e falou da mesma maneira aos seus habitantes; e os homens de Fanuel responderam-lhe como tinham respondido os homens de Sucot."},
{v:9,t:"Disse também aos homens de Fanuel: Quando eu voltar em paz, derrubarei esta torre."},
{v:10,t:"Zebá e Salmana estavam em Carcor com os seus exércitos, uns quinze mil homens, todos os que tinham restado de todo o exército dos filhos do Oriente; tinham caído cento e vinte mil homens que empunhavam a espada.",np:1},
{v:11,t:"Gedeão subiu pelo caminho dos nômades, a leste de Nobé e de Jegbaá, e atacou o acampamento, que se julgava em segurança."},
{v:12,t:"Zebá e Salmana fugiram; mas ele os perseguiu e prendeu os dois reis de Madiã, Zebá e Salmana, e desbaratou todo o exército."},
{v:13,t:"Gedeão, filho de Joás, voltou da batalha pela subida de Heres.",np:1},
{v:14,t:"Apanhou um jovem dos homens de Sucot e interrogou-o; e o jovem escreveu-lhe os nomes dos chefes e dos anciãos de Sucot, setenta e sete homens.",n:"Um jovem qualquer sabe escrever: é um dos testemunhos mais antigos da difusão da escrita alfabética em Israel."},
{v:15,t:"Depois foi ter com os homens de Sucot e disse: Eis Zebá e Salmana, a respeito dos quais me insultastes, dizendo: Porventura já tens nas mãos as palmas das mãos de Zebá e Salmana, para que demos pão aos teus homens exaustos?"},
{v:16,t:"Tomou os anciãos da cidade e, com os espinhos e os cardos do deserto, castigou os homens de Sucot."},
{v:17,t:"Derrubou também a torre de Fanuel e matou os homens da cidade."},
{v:18,t:"Depois disse a Zebá e a Salmana: Como eram os homens que matastes no Tabor? Eles responderam: Eram como tu; cada um tinha o porte de filho de rei.",np:1},
{v:19,t:"Ele disse: Eram meus irmãos, filhos de minha mãe. Pela vida do Senhor, se os tivésseis deixado viver, eu não vos mataria!",n:"A guerra contra Madiã é também, para Gedeão, a vingança do sangue dos irmãos."},
{v:20,t:"E disse a Jéter, seu primogênito: Levanta-te e mata-os! Mas o jovem não desembainhou a espada, porque tinha medo, pois ainda era um menino."},
{v:21,t:"Zebá e Salmana disseram: Levanta-te tu e ataca-nos, porque tal é o homem, tal a sua força. Gedeão levantou-se, matou Zebá e Salmana e tomou os crescentes que os seus camelos traziam ao pescoço."},
{s:"Gedeão recusa ser rei"},
{v:22,t:"Os homens de Israel disseram a Gedeão: Reina sobre nós, tu, o teu filho e o filho do teu filho, pois nos livraste da mão de Madiã.",np:1},
{v:23,t:"Gedeão respondeu-lhes: Não reinarei sobre vós, nem o meu filho reinará sobre vós: o Senhor é quem reinará sobre vós.",n:"A recusa de Gedeão exprime uma corrente antiga de Israel, desconfiada da realeza: o único rei de Israel é o Senhor. Os livros de Samuel retomarão o debate."},
{v:24,t:"E disse-lhes: Só vos peço uma coisa: dai-me cada um os anéis do vosso despojo. Pois os inimigos, sendo ismaelitas, tinham anéis de ouro."},
{v:25,t:"Eles responderam: Nós os daremos de boa vontade. Estenderam um manto, e cada um lançou nele os anéis do seu despojo."},
{v:26,t:"O peso dos anéis de ouro que ele pediu foi de mil e setecentos siclos de ouro, sem contar os crescentes, os brincos e as vestes de púrpura que os reis de Madiã usavam, e sem os colares do pescoço dos seus camelos.",n:"Mil e setecentos siclos são uns vinte quilos de ouro."},
{v:27,t:"Gedeão fez com isso um efod e o colocou na sua cidade, em Efra; e todo o Israel se prostituiu ali atrás dele, e isso tornou-se uma armadilha para Gedeão e para a sua casa.",n:"O efod era aqui um objeto de culto, talvez uma imagem revestida ou um instrumento de consulta a Deus. O homem que recusou a coroa cria, com o ouro dos vencidos, um ídolo: o herói tem os pés de barro."},
{v:28,t:"Madiã foi humilhado diante dos filhos de Israel e não voltou a levantar a cabeça; e a terra descansou quarenta anos, durante a vida de Gedeão."},
{s:"Morte de Gedeão"},
{v:29,t:"Jerobaal, filho de Joás, foi e habitou em sua casa.",np:1},
{v:30,t:"Gedeão teve setenta filhos, nascidos dele, porque tinha muitas mulheres."},
{v:31,t:"Também a sua concubina, que estava em Siquém, deu-lhe um filho, a quem ele pôs o nome de Abimelec.",n:"Abimelec quer dizer meu pai é rei: o nome contradiz a recusa de Gedeão."},
{v:32,t:"Gedeão, filho de Joás, morreu em boa velhice e foi sepultado no sepulcro de Joás, seu pai, em Efra dos abiezritas."},
{v:33,t:"Depois da morte de Gedeão, os filhos de Israel voltaram a prostituir-se com os baais e tomaram por deus Baal-Berit.",np:1,n:"Baal-Berit quer dizer Baal da aliança: era o deus de Siquém, a cidade onde Josué renovara a aliança com o Senhor."},
{v:34,t:"Os filhos de Israel não se lembraram do Senhor seu Deus, que os livrara da mão de todos os inimigos que os rodeavam;"},
{v:35,t:"e não foram leais com a casa de Jerobaal, isto é, de Gedeão, segundo todo o bem que ele fizera a Israel."}
];

window.TEXTOS_SEED["juizes"][9] = [
{s:"Abimelec, rei em Siquém"},
{v:1,t:"Abimelec, filho de Jerobaal, foi a Siquém, aos irmãos de sua mãe, e falou a eles e a todo o clã da família de sua mãe, dizendo:"},
{v:2,t:"Dizei a todos os senhores de Siquém: Que é melhor para vós, que reinem sobre vós setenta homens, todos os filhos de Jerobaal, ou que reine sobre vós um só homem? Lembrai-vos também de que eu sou osso vosso e carne vossa.",n:"Os senhores de Siquém, os baalim da cidade, são os notáveis. O capítulo joga com a palavra baal, que quer dizer senhor e é o nome do deus."},
{v:3,t:"Os irmãos de sua mãe falaram a todos os senhores de Siquém todas estas palavras a respeito dele, e o coração deles inclinou-se para Abimelec, porque diziam: É nosso irmão."},
{v:4,t:"Deram-lhe setenta siclos de prata do templo de Baal-Berit, e com eles Abimelec contratou homens vadios e aventureiros, que o seguiram."},
{v:5,t:"Foi à casa de seu pai, em Efra, e matou seus irmãos, os filhos de Jerobaal, setenta homens, sobre uma mesma pedra. Mas Joatão, o filho mais novo de Jerobaal, escapou, porque se tinha escondido.",n:"Sobre uma mesma pedra: como numa execução, ou num sacrifício. A realeza começa em Israel com um fratricídio."},
{v:6,t:"Todos os senhores de Siquém e toda a gente de Bet-Melo reuniram-se e foram proclamar rei Abimelec, junto ao carvalho da estela que há em Siquém."},
{s:"A fábula de Joatão"},
{v:7,t:"Quando anunciaram isto a Joatão, ele foi, subiu ao cume do monte Garizim, levantou a voz e gritou-lhes: Ouvi-me, senhores de Siquém, para que Deus vos ouça!",np:1,n:"A fábula de Joatão é a mais antiga da Bíblia, e uma das mais antigas fábulas políticas que se conhecem. As árvores úteis recusam o poder; só o espinheiro, que nada produz, o aceita."},
{v:8,t:"As árvores puseram-se a caminho para ungir um rei que reinasse sobre elas. Disseram à oliveira: Reina sobre nós."},
{v:9,t:"Mas a oliveira respondeu-lhes: Hei de renunciar ao meu azeite, com que se honram os deuses e os homens, para ir balançar-me sobre as árvores?"},
{v:10,t:"Então as árvores disseram à figueira: Vem tu, reina sobre nós."},
{v:11,t:"Mas a figueira respondeu-lhes: Hei de renunciar à minha doçura e ao meu bom fruto, para ir balançar-me sobre as árvores?"},
{v:12,t:"Então as árvores disseram à videira: Vem tu, reina sobre nós."},
{v:13,t:"Mas a videira respondeu-lhes: Hei de renunciar ao meu vinho, que alegra os deuses e os homens, para ir balançar-me sobre as árvores?"},
{v:14,t:"Então todas as árvores disseram ao espinheiro: Vem tu, reina sobre nós."},
{v:15,t:"E o espinheiro respondeu às árvores: Se é de boa-fé que me ungis como vosso rei, vinde abrigar-vos à minha sombra; se não, saia fogo do espinheiro e devore os cedros do Líbano!",n:"Um espinheiro não dá sombra, e pega fogo com facilidade: a oferta de proteção é ridícula, a ameaça é real."},
{v:16,t:"Agora, pois, se agistes com fidelidade e retidão fazendo rei Abimelec, se procedestes bem com Jerobaal e com a sua casa, e se lhe retribuístes como merecia a obra das suas mãos —",np:1},
{v:17,t:"meu pai combateu por vós, arriscou a vida e vos livrou da mão de Madiã,"},
{v:18,t:"e vós hoje vos levantastes contra a casa de meu pai, matastes os seus filhos, setenta homens, sobre uma mesma pedra, e proclamastes rei sobre os senhores de Siquém Abimelec, filho da sua serva, porque é vosso irmão —,"},
{v:19,t:"se, pois, agistes hoje com fidelidade e retidão para com Jerobaal e a sua casa, alegrai-vos com Abimelec, e ele se alegre convosco."},
{v:20,t:"Mas, se não, saia fogo de Abimelec e devore os senhores de Siquém e Bet-Melo, e saia fogo dos senhores de Siquém e de Bet-Melo e devore Abimelec!"},
{v:21,t:"Depois Joatão fugiu, escapou e foi para Bera, onde ficou, por medo de Abimelec, seu irmão."},
{s:"A revolta de Siquém"},
{v:22,t:"Abimelec governou Israel durante três anos.",np:1},
{v:23,t:"Então Deus enviou um espírito de discórdia entre Abimelec e os senhores de Siquém, e os senhores de Siquém traíram Abimelec,",n:"Deus enviou: a Bíblia atribui a Deus as consequências do mal, que se voltam contra quem o fez. O mal destrói os seus próprios aliados."},
{v:24,t:"para que o crime cometido contra os setenta filhos de Jerobaal fosse vingado, e o seu sangue recaísse sobre Abimelec, seu irmão, que os matara, e sobre os senhores de Siquém, que o tinham ajudado a matar os seus irmãos."},
{v:25,t:"Os senhores de Siquém puseram contra ele emboscadas nos cumes dos montes e assaltavam todos os que passavam por aquele caminho. E isso foi comunicado a Abimelec."},
{v:26,t:"Gaal, filho de Obed, chegou com os seus irmãos e passou a Siquém, e os senhores de Siquém puseram nele a sua confiança.",np:1},
{v:27,t:"Saíram ao campo, vindimaram as suas vinhas, pisaram as uvas e fizeram festa; entraram no templo do seu deus, comeram e beberam, e amaldiçoaram Abimelec."},
{v:28,t:"Gaal, filho de Obed, disse: Quem é Abimelec, e quem é Siquém, para que o sirvamos? Não é ele filho de Jerobaal, e Zebul, o seu delegado? Servi antes aos homens de Hamor, pai de Siquém! Por que haveríamos de servi-lo?",n:"Hamor era o antigo senhor cananeu de Siquém, no tempo de Jacó. Gaal apela ao orgulho da aristocracia local contra o filho de um israelita."},
{v:29,t:"Quem me dera ter este povo nas minhas mãos! Eu tiraria Abimelec do caminho. E diria a Abimelec: Reforça o teu exército e sai!"},
{v:30,t:"Zebul, governador da cidade, ouviu as palavras de Gaal, filho de Obed, e ficou muito irritado.",np:1},
{v:31,t:"Enviou secretamente mensageiros a Abimelec, dizendo: Gaal, filho de Obed, e os seus irmãos vieram a Siquém e estão sublevando a cidade contra ti."},
{v:32,t:"Levanta-te, pois, de noite, tu e o povo que está contigo, e põe-te de emboscada no campo."},
{v:33,t:"De manhã, ao nascer do sol, levanta-te cedo e cai sobre a cidade; e, quando ele sair contra ti com o povo que o acompanha, faze-lhe o que puderes."},
{v:34,t:"Abimelec levantou-se de noite com todo o povo que estava com ele, e puseram-se de emboscada contra Siquém, em quatro grupos.",np:1},
{v:35,t:"Gaal, filho de Obed, saiu e parou à entrada da porta da cidade; e Abimelec e o povo que estava com ele saíram da emboscada."},
{v:36,t:"Gaal viu o povo e disse a Zebul: Olha, vem gente descendo do cume dos montes. Zebul respondeu-lhe: Estás vendo a sombra dos montes como se fossem homens."},
{v:37,t:"Gaal voltou a falar: Olha, vem gente descendo do Umbigo da Terra, e um grupo vem pelo caminho do Carvalho dos Adivinhos.",n:"O Umbigo da Terra era um lugar alto junto de Siquém, tido pelos antigos como o centro do mundo."},
{v:38,t:"Zebul disse-lhe: Onde está agora a tua boca, tu que dizias: Quem é Abimelec, para que o sirvamos? Não é este o povo que desprezavas? Sai agora e combate contra ele!"},
{v:39,t:"Gaal saiu à frente dos senhores de Siquém e combateu contra Abimelec."},
{v:40,t:"Abimelec perseguiu-o, e ele fugiu diante dele, e muitos caíram mortos até a entrada da porta."},
{v:41,t:"Abimelec ficou em Aruma, e Zebul expulsou Gaal e os seus irmãos, para que não habitassem em Siquém."},
{s:"A destruição de Siquém"},
{v:42,t:"No dia seguinte, o povo saiu ao campo, e isso foi comunicado a Abimelec.",np:1},
{v:43,t:"Ele tomou a sua gente, dividiu-a em três grupos e pôs-se de emboscada no campo; e, vendo que o povo saía da cidade, levantou-se contra eles e derrotou-os."},
{v:44,t:"Abimelec e os grupos que estavam com ele avançaram e pararam à entrada da porta da cidade, enquanto os outros dois grupos caíram sobre todos os que estavam no campo e os derrotaram."},
{v:45,t:"Abimelec combateu contra a cidade durante todo aquele dia; tomou a cidade, matou o povo que nela estava, arrasou a cidade e semeou-a de sal.",n:"Semear sal era um rito de maldição: que o lugar ficasse estéril para sempre. Siquém, porém, será reconstruída, e Jeroboão fará dela a sua capital."},
{v:46,t:"Quando os senhores da torre de Siquém souberam disso, entraram na cripta do templo de El-Berit.",np:1,n:"El-Berit, o deus da aliança, é o mesmo Baal-Berit do capítulo 8."},
{v:47,t:"Informaram Abimelec de que todos os senhores da torre de Siquém se tinham reunido ali."},
{v:48,t:"Abimelec subiu ao monte Selmon, ele e todo o povo que estava com ele; tomou um machado, cortou um ramo de árvore, levantou-o e o pôs no ombro, e disse ao povo que estava com ele: O que me vistes fazer, fazei-o depressa como eu."},
{v:49,t:"Cada um do povo cortou também o seu ramo, e seguiram Abimelec; puseram os ramos contra a cripta e atearam-lhe fogo com eles dentro; e morreram também todos os da torre de Siquém, cerca de mil homens e mulheres.",n:"Cumpre-se a fábula: saiu fogo de Abimelec e devorou os senhores de Siquém."},
{v:50,t:"Depois Abimelec foi a Tebes, cercou-a e tomou-a.",np:1},
{v:51,t:"Havia no meio da cidade uma torre forte, onde se refugiaram todos os homens e mulheres, todos os senhores da cidade; fecharam-se nela e subiram ao terraço da torre."},
{v:52,t:"Abimelec chegou até a torre, atacou-a e aproximou-se da porta da torre para lhe atear fogo."},
{v:53,t:"Mas uma mulher lançou uma mó de moinho sobre a cabeça de Abimelec e partiu-lhe o crânio.",n:"Era a mó de cima do moinho doméstico, que as mulheres manejavam todos os dias. O Segundo Livro de Samuel lembrará a morte de Abimelec como exemplo da imprudência de chegar perto demais de uma muralha."},
{v:54,t:"Ele chamou depressa o jovem que lhe levava as armas e disse-lhe: Desembainha a tua espada e mata-me, para que não se diga de mim: Uma mulher o matou. O jovem traspassou-o, e ele morreu."},
{v:55,t:"Quando os homens de Israel viram que Abimelec estava morto, foram cada um para a sua casa."},
{v:56,t:"Assim Deus fez recair sobre Abimelec o mal que ele fizera a seu pai, matando os seus setenta irmãos;",np:1},
{v:57,t:"e também sobre os homens de Siquém Deus fez recair todo o mal que tinham feito; e veio sobre eles a maldição de Joatão, filho de Jerobaal.",n:"Os versículos 56 e 57 dão a chave do capítulo: a justiça de Deus age por dentro da história, fazendo o mal voltar-se contra quem o comete."}
];

window.TEXTOS_SEED["juizes"][10] = [
{s:"Tola e Jair"},
{v:1,t:"Depois de Abimelec, levantou-se para salvar Israel Tola, filho de Fua, filho de Dodô, homem de Issacar, que habitava em Samir, na montanha de Efraim."},
{v:2,t:"Julgou Israel durante vinte e três anos; depois morreu e foi sepultado em Samir."},
{v:3,t:"Depois dele levantou-se Jair, o galaadita, que julgou Israel durante vinte e dois anos.",np:1},
{v:4,t:"Ele tinha trinta filhos, que montavam trinta jumentinhos e possuíam trinta cidades, chamadas até o dia de hoje Havot-Jair, na terra de Galaad.",n:"Havot-Jair quer dizer aldeias de Jair. Montar jumentos era sinal de posição social; o número trinta, repetido três vezes, diz a prosperidade da família."},
{v:5,t:"Jair morreu e foi sepultado em Camon."},
{s:"A opressão dos amonitas"},
{v:6,t:"Os filhos de Israel voltaram a fazer o que era mau aos olhos do Senhor: serviram os baais e as Astartes, os deuses de Aram, os deuses de Sidônia, os deuses de Moab, os deuses dos filhos de Amon e os deuses dos filisteus; abandonaram o Senhor e não o serviram mais.",np:1,n:"Sete grupos de deuses: a idolatria chega ao cúmulo."},
{v:7,t:"A ira do Senhor inflamou-se contra Israel, e ele os entregou nas mãos dos filisteus e nas mãos dos filhos de Amon."},
{v:8,t:"Naquele ano, e durante dezoito anos, eles oprimiram e esmagaram os filhos de Israel, todos os filhos de Israel que estavam do outro lado do Jordão, na terra dos amorreus, em Galaad."},
{v:9,t:"Os filhos de Amon atravessaram também o Jordão para combater contra Judá, contra Benjamim e contra a casa de Efraim; e Israel ficou em grande aflição."},
{v:10,t:"Os filhos de Israel clamaram ao Senhor, dizendo: Pecamos contra ti, porque abandonamos o nosso Deus e servimos os baais.",np:1},
{v:11,t:"O Senhor respondeu aos filhos de Israel: Não vos oprimiram os egípcios, os amorreus, os filhos de Amon e os filisteus,"},
{v:12,t:"os sidônios, Amalec e Madiã, e não clamastes a mim, e eu vos livrei das suas mãos?"},
{v:13,t:"E, contudo, vós me abandonastes e servistes outros deuses; por isso não vos livrarei mais."},
{v:14,t:"Ide e clamai aos deuses que escolhestes: que eles vos livrem no tempo da vossa angústia!",n:"A ironia de Deus é a de um amor ferido: é a resposta do Deuteronômio aos que trocam o Senhor por ídolos que não salvam."},
{v:15,t:"Os filhos de Israel disseram ao Senhor: Pecamos. Faze conosco o que te parecer bem; mas livra-nos hoje, por favor."},
{v:16,t:"Tiraram do meio deles os deuses estrangeiros e serviram o Senhor; e ele não pôde mais suportar a miséria de Israel.",n:"À letra, a sua alma encurtou-se com a miséria de Israel: a impaciência do amor, que não aguenta ver sofrer. Deus acaba de dizer que não os livraria; volta atrás diante da conversão."},
{v:17,t:"Os filhos de Amon foram convocados e acamparam em Galaad; os filhos de Israel reuniram-se e acamparam em Masfa.",np:1},
{v:18,t:"O povo e os chefes de Galaad disseram uns aos outros: Quem é o homem que começará a combater contra os filhos de Amon? Será chefe de todos os habitantes de Galaad."}
];

window.TEXTOS_SEED["juizes"][11] = [
{s:"Jefté"},
{v:1,t:"Jefté, o galaadita, era um guerreiro valente; era filho de uma prostituta, e Galaad o tinha gerado."},
{v:2,t:"A mulher de Galaad também lhe deu filhos, e, quando estes cresceram, expulsaram Jefté, dizendo: Não terás herança na casa de nosso pai, porque és filho de outra mulher."},
{v:3,t:"Jefté fugiu de seus irmãos e habitou na terra de Tob; juntaram-se a ele homens vadios, que saíam com ele em incursões.",n:"Como Davi mais tarde, Jefté é um marginal à frente de um bando. Deus escolhe os seus instrumentos onde quer."},
{v:4,t:"Algum tempo depois, os filhos de Amon fizeram guerra a Israel.",np:1},
{v:5,t:"Quando os filhos de Amon atacaram Israel, os anciãos de Galaad foram buscar Jefté na terra de Tob."},
{v:6,t:"E disseram a Jefté: Vem e sê o nosso comandante, para que combatamos contra os filhos de Amon."},
{v:7,t:"Jefté respondeu aos anciãos de Galaad: Não fostes vós que me odiastes e me expulsastes da casa de meu pai? Por que vindes agora a mim, quando estais em apuros?"},
{v:8,t:"Os anciãos de Galaad disseram a Jefté: É por isso mesmo que agora voltamos a ti: vem conosco, combate contra os filhos de Amon, e serás o nosso chefe, de todos os habitantes de Galaad."},
{v:9,t:"Jefté disse aos anciãos de Galaad: Se me fazeis voltar para combater contra os filhos de Amon, e o Senhor os entregar a mim, serei o vosso chefe."},
{v:10,t:"Os anciãos de Galaad responderam a Jefté: O Senhor seja testemunha entre nós: faremos segundo a tua palavra."},
{v:11,t:"Jefté foi com os anciãos de Galaad, e o povo o constituiu chefe e comandante; e Jefté repetiu todas as suas palavras diante do Senhor, em Masfa."},
{s:"Jefté e o rei dos amonitas"},
{v:12,t:"Jefté enviou mensageiros ao rei dos filhos de Amon, dizendo: Que há entre mim e ti, para que venhas contra mim fazer guerra à minha terra?",np:1},
{v:13,t:"O rei dos filhos de Amon respondeu aos mensageiros de Jefté: É que Israel, quando subiu do Egito, tomou a minha terra, desde o Arnon até o Jaboc e até o Jordão. Agora, pois, restitui-a em paz."},
{v:14,t:"Jefté enviou de novo mensageiros ao rei dos filhos de Amon,"},
{v:15,t:"e disse-lhe: Assim diz Jefté: Israel não tomou a terra de Moab nem a terra dos filhos de Amon.",n:"O discurso de Jefté resume a história dos Números: Israel contornou Edom e Moab e só combateu contra Seon, rei dos amorreus, que lhe negou passagem. O território disputado não era amonita, mas amorreu."},
{v:16,t:"Quando Israel subiu do Egito, andou pelo deserto até o mar Vermelho e chegou a Cades."},
{v:17,t:"Enviou mensageiros ao rei de Edom, dizendo: Deixa-me passar pela tua terra. Mas o rei de Edom não quis ouvir. Enviou também ao rei de Moab, que também não quis. E Israel ficou em Cades."},
{v:18,t:"Depois caminhou pelo deserto, contornou a terra de Edom e a terra de Moab e chegou a leste da terra de Moab; acamparam do outro lado do Arnon, mas não entraram no território de Moab, porque o Arnon é a fronteira de Moab."},
{v:19,t:"Então Israel enviou mensageiros a Seon, rei dos amorreus, rei de Hesbon, e disse-lhe: Deixa-nos passar pela tua terra até o nosso lugar."},
{v:20,t:"Mas Seon não confiou em Israel para deixá-lo passar pelo seu território; reuniu todo o seu povo, acampou em Jasa e combateu contra Israel."},
{v:21,t:"O Senhor, Deus de Israel, entregou Seon e todo o seu povo nas mãos de Israel, que os derrotou; e Israel tomou posse de toda a terra dos amorreus que habitavam aquela região."},
{v:22,t:"Tomaram posse de todo o território dos amorreus, desde o Arnon até o Jaboc e desde o deserto até o Jordão."},
{v:23,t:"Assim o Senhor, Deus de Israel, desalojou os amorreus diante do seu povo Israel; e tu queres agora tomar posse da terra deles?",np:1},
{v:24,t:"Não possuis tu aquilo que Camos, o teu deus, te deu em posse? Pois nós possuiremos tudo o que o Senhor nosso Deus desalojou diante de nós.",n:"Camos era o deus de Moab; o dos amonitas era Milcom: Jefté fala talvez a um rei que dominava as duas terras. Não reconhece Camos como Deus; usa a linguagem do adversário para argumentar."},
{v:25,t:"Porventura és tu melhor do que Balac, filho de Sefor, rei de Moab? Acaso ele disputou com Israel, ou lhe fez guerra?"},
{v:26,t:"Israel habita em Hesbon e nas suas aldeias, em Aroer e nas suas aldeias, e em todas as cidades que estão às margens do Arnon, há trezentos anos: por que não as retomastes durante todo esse tempo?",n:"Trezentos anos é aproximadamente a soma dos anos de opressão e de descanso dos capítulos anteriores. É um número de retórica, para dizer que a posse é antiga."},
{v:27,t:"Não fui eu que pequei contra ti; és tu que procedes mal comigo, fazendo-me guerra. Que o Senhor, o Juiz, julgue hoje entre os filhos de Israel e os filhos de Amon."},
{v:28,t:"Mas o rei dos filhos de Amon não escutou as palavras que Jefté lhe mandara dizer."},
{s:"O voto de Jefté"},
{v:29,t:"O Espírito do Senhor veio sobre Jefté, e ele atravessou Galaad e Manassés, passou a Masfa de Galaad, e de Masfa de Galaad passou contra os filhos de Amon.",np:1},
{v:30,t:"Jefté fez um voto ao Senhor, dizendo: Se entregares os filhos de Amon nas minhas mãos,"},
{v:31,t:"quem sair primeiro das portas da minha casa ao meu encontro, quando eu voltar em paz dos filhos de Amon, será do Senhor, e eu o oferecerei em holocausto.",n:"Nota do tradutor: o voto é ambíguo desde a primeira palavra — quem sair, ou o que sair: nas casas antigas, os animais viviam no térreo. Mas Jefté fala de quem vem ao encontro, e um guerreiro que volta vitorioso é recebido por pessoas. A Lei de Moisés proibia os sacrifícios humanos como abominação dos cananeus. O voto já é, em si, um erro: Deus não pedia nada."},
{v:32,t:"Jefté passou contra os filhos de Amon para combatê-los, e o Senhor entregou-os nas suas mãos."},
{v:33,t:"Derrotou-os desde Aroer até a entrada de Menit, vinte cidades, e até Abel-Carmim, com uma derrota muito grande; e os filhos de Amon foram humilhados diante dos filhos de Israel."},
{v:34,t:"Quando Jefté voltou a Masfa, para a sua casa, eis que sua filha saiu ao seu encontro com tamborins e danças. Era a sua única filha; além dela, não tinha filho nem filha.",np:1,n:"Com tamborins e danças: como Míriam depois do mar Vermelho, as mulheres celebravam as vitórias. A filha faz o que se esperava de uma filha."},
{v:35,t:"Ao vê-la, ele rasgou as suas vestes e disse: Ai, minha filha! Tu me abateste completamente, tu és a causa da minha desgraça! Fiz uma promessa ao Senhor e não posso voltar atrás."},
{v:36,t:"Ela respondeu-lhe: Meu pai, se fizeste uma promessa ao Senhor, faze-me conforme o que prometeste, já que o Senhor te concedeu vingança dos teus inimigos, os filhos de Amon."},
{v:37,t:"E disse a seu pai: Concede-me só isto: deixa-me dois meses, para que eu vá pelos montes e chore a minha virgindade com as minhas companheiras.",n:"Chorar a virgindade: morrer sem ter sido mãe, sem descendência, era para uma mulher de Israel a maior desolação."},
{v:38,t:"Ele disse: Vai. E deixou-a ir por dois meses. Ela foi com as suas companheiras e chorou a sua virgindade pelos montes."},
{v:39,t:"Ao fim dos dois meses, voltou para seu pai, e ele cumpriu nela o voto que fizera. Ela não tinha conhecido homem. Daí veio o costume em Israel:",n:"Nota do tradutor: o texto não diz que a jovem foi queimada, mas diz que o pai cumpriu nela o voto de um holocausto. Desde a Idade Média, alguns intérpretes judeus e cristãos entenderam que ela foi consagrada a Deus em virgindade perpétua, e não morta; a maior parte dos antigos leu um sacrifício real e o condenou. O narrador não aprova: conta. O livro mostra um Israel em decadência, e este é um dos seus momentos mais sombrios. Deus não pediu o voto, e a Escritura não diz que o aceitou. A Carta aos Hebreus lembra Jefté entre os homens de fé pela sua vitória, e não por este gesto."},
{v:40,t:"todos os anos, as filhas de Israel vão durante quatro dias lamentar a filha de Jefté, o galaadita."}
];

window.TEXTOS_SEED["juizes"][12] = [
{s:"Jefté e os efraimitas"},
{v:1,t:"Os homens de Efraim reuniram-se, passaram para o norte e disseram a Jefté: Por que foste combater contra os filhos de Amon sem nos chamares para irmos contigo? Vamos queimar a tua casa contigo dentro!"},
{v:2,t:"Jefté respondeu-lhes: Eu e o meu povo tivemos uma grande disputa com os filhos de Amon; chamei-vos, e não me livrastes das suas mãos."},
{v:3,t:"Vendo que não me socorríeis, arrisquei a minha vida e passei contra os filhos de Amon, e o Senhor os entregou nas minhas mãos. Por que subistes hoje contra mim, para me combater?"},
{v:4,t:"Jefté reuniu todos os homens de Galaad e combateu contra Efraim; e os homens de Galaad derrotaram Efraim, porque estes diziam: Vós, galaaditas, sois fugitivos de Efraim, no meio de Efraim e de Manassés.",n:"O insulto dos efraimitas é obscuro: tratavam os galaaditas como desertores, gente sem tribo."},
{v:5,t:"Os galaaditas ocuparam os vaus do Jordão, antes que os de Efraim chegassem; e, quando algum fugitivo de Efraim dizia: Deixai-me passar, os homens de Galaad perguntavam-lhe: És efraimita? Se ele respondia: Não,"},
{v:6,t:"diziam-lhe: Então dize: Chibolet. Ele dizia: Sibolet, porque não conseguia pronunciar direito. Então o agarravam e o matavam junto aos vaus do Jordão. Naquele tempo caíram quarenta e dois mil homens de Efraim.",n:"Chibolet quer dizer espiga, e também corrente de água. Os efraimitas não pronunciavam o som ch. A palavra passou a muitas línguas para designar uma senha que denuncia a origem de alguém. Depois de libertar Israel dos inimigos, os juízes começam a combater os irmãos."},
{v:7,t:"Jefté julgou Israel durante seis anos; depois Jefté, o galaadita, morreu e foi sepultado na sua cidade, em Galaad."},
{s:"Abesã, Elon e Abdon"},
{v:8,t:"Depois dele, julgou Israel Abesã, de Belém.",np:1},
{v:9,t:"Teve trinta filhos e trinta filhas, que casou fora do seu clã; e trouxe de fora trinta mulheres para os seus filhos. Julgou Israel durante sete anos;"},
{v:10,t:"depois Abesã morreu e foi sepultado em Belém.",n:"Esta Belém é talvez a da Galileia, em Zabulon, e não a de Judá."},
{v:11,t:"Depois dele, julgou Israel Elon, o zabulonita, que julgou Israel durante dez anos;"},
{v:12,t:"depois Elon, o zabulonita, morreu e foi sepultado em Aialon, na terra de Zabulon."},
{v:13,t:"Depois dele, julgou Israel Abdon, filho de Hilel, o faratonita."},
{v:14,t:"Teve quarenta filhos e trinta netos, que montavam setenta jumentinhos. Julgou Israel durante oito anos;"},
{v:15,t:"depois Abdon, filho de Hilel, o faratonita, morreu e foi sepultado em Faraton, na terra de Efraim, na montanha dos amalecitas."}
];

window.TEXTOS_SEED["juizes"][13] = [
{s:"O anúncio do nascimento de Sansão"},
{v:1,t:"Os filhos de Israel voltaram a fazer o que era mau aos olhos do Senhor, e o Senhor os entregou nas mãos dos filisteus durante quarenta anos.",n:"Os filisteus, um dos Povos do Mar vindos do Egeu no século XII antes de Cristo, instalaram-se na costa sul de Canaã e dominavam a metalurgia do ferro. Por meio dos gregos e dos romanos, deram à terra o nome de Palestina."},
{v:2,t:"Havia um homem de Saraá, do clã dos danitas, chamado Manué; a sua mulher era estéril e não tinha filhos.",np:1,n:"A mulher estéril a quem Deus dá um filho, como Sara, Rebeca, Raquel, a mãe de Samuel e Isabel: o nascimento é dom, e o filho tem uma missão."},
{v:3,t:"O anjo do Senhor apareceu à mulher e disse-lhe: Eis que és estéril e não tens filhos; mas conceberás e darás à luz um filho."},
{v:4,t:"Agora, pois, guarda-te de beber vinho ou bebida fermentada, e não comas nada impuro,"},
{v:5,t:"porque vais conceber e dar à luz um filho. Navalha não passará pela sua cabeça, porque o menino será nazireu de Deus desde o ventre materno; e ele começará a livrar Israel das mãos dos filisteus.",n:"O nazireu era consagrado a Deus: não bebia vinho, não cortava o cabelo, não tocava cadáveres, segundo o livro dos Números. O voto costumava ser temporário; o de Sansão é para a vida inteira e começa antes do nascimento — por isso também a mãe se abstém. Começará: a libertação dos filisteus só será completa com Davi."},
{v:6,t:"A mulher foi dizer ao marido: Um homem de Deus veio a mim; o seu aspecto era como o de um anjo de Deus, muito terrível. Não lhe perguntei de onde era, e ele não me disse o seu nome."},
{v:7,t:"Mas disse-me: Vais conceber e dar à luz um filho; agora, pois, não bebas vinho nem bebida fermentada, e não comas nada impuro, porque o menino será nazireu de Deus desde o ventre materno até o dia da sua morte.",n:"Até o dia da sua morte: a mãe acrescenta, sem saber, o que o anjo não dissera, e que se cumprirá."},
{v:8,t:"Manué orou ao Senhor, dizendo: Ah, Senhor! Que o homem de Deus que enviaste volte a nós e nos ensine o que devemos fazer com o menino que vai nascer.",np:1},
{v:9,t:"Deus ouviu a voz de Manué, e o anjo de Deus voltou à mulher, quando ela estava sentada no campo; mas Manué, seu marido, não estava com ela."},
{v:10,t:"A mulher correu depressa a avisar o marido e disse-lhe: Eis que me apareceu o homem que veio a mim no outro dia."},
{v:11,t:"Manué levantou-se, seguiu a mulher, chegou até o homem e perguntou-lhe: És tu o homem que falou a esta mulher? Ele respondeu: Sou eu."},
{v:12,t:"Manué disse: Quando se cumprir a tua palavra, qual será a regra de vida do menino, e o que ele deverá fazer?"},
{v:13,t:"O anjo do Senhor respondeu a Manué: Que a mulher se abstenha de tudo o que eu lhe disse:"},
{v:14,t:"não coma nada do que procede da videira, não beba vinho nem bebida fermentada, não coma nada impuro; que observe tudo o que lhe ordenei."},
{v:15,t:"Manué disse ao anjo do Senhor: Permite que te retenhamos e te preparemos um cabrito.",np:1},
{v:16,t:"O anjo do Senhor respondeu a Manué: Ainda que me retenhas, não comerei do teu pão; mas, se queres oferecer um holocausto, oferece-o ao Senhor. Manué não sabia que era o anjo do Senhor."},
{v:17,t:"Manué disse ao anjo do Senhor: Qual é o teu nome, para que te honremos quando se cumprir a tua palavra?"},
{v:18,t:"O anjo do Senhor respondeu-lhe: Por que perguntas pelo meu nome? Ele é maravilhoso.",n:"Maravilhoso, peli: o mesmo adjetivo que Isaías dará ao Menino prometido, cujo nome será Conselheiro Maravilhoso. O nome de Deus não se deixa possuir."},
{v:19,t:"Manué tomou o cabrito e a oblação e ofereceu-os sobre a rocha ao Senhor, que faz maravilhas; e Manué e a sua mulher olhavam."},
{v:20,t:"Quando a chama subia do altar para o céu, o anjo do Senhor subiu na chama do altar. Vendo isso, Manué e a sua mulher prostraram-se com o rosto por terra;"},
{v:21,t:"e o anjo do Senhor não voltou a aparecer a Manué e à sua mulher. Então Manué compreendeu que era o anjo do Senhor,"},
{v:22,t:"e disse à sua mulher: Certamente vamos morrer, porque vimos Deus."},
{v:23,t:"Mas a mulher respondeu-lhe: Se o Senhor quisesse matar-nos, não teria aceitado da nossa mão o holocausto e a oblação, nem nos teria mostrado todas estas coisas, nem nos teria feito ouvir agora tais palavras.",n:"A mulher, que nem nome tem no relato, é quem raciocina com fé; o marido tem medo. O anjo dirigira-se primeiro a ela."},
{v:24,t:"A mulher deu à luz um filho e pôs-lhe o nome de Sansão. O menino cresceu, e o Senhor o abençoou.",np:1,n:"Sansão, Shimshon, vem de shemesh, sol: pequeno sol. Bet-Sames, a casa do sol, ficava perto."},
{v:25,t:"E o Espírito do Senhor começou a impeli-lo em Maané-Dã, entre Saraá e Estaol.",n:"Maané-Dã quer dizer acampamento de Dã."}
];

window.TEXTOS_SEED["juizes"][14] = [
{s:"O casamento de Sansão em Tamna"},
{v:1,t:"Sansão desceu a Tamna e viu ali uma mulher, uma das filhas dos filisteus."},
{v:2,t:"Subiu e contou-o a seu pai e a sua mãe, dizendo: Vi em Tamna uma mulher, uma das filhas dos filisteus; tomai-a agora para mim por mulher."},
{v:3,t:"Seu pai e sua mãe disseram-lhe: Não há mulher entre as filhas de teus irmãos e em todo o meu povo, para ires tomar mulher dos filisteus incircuncisos? Sansão respondeu a seu pai: Toma-a para mim, porque ela me agrada.",n:"Ela me agrada, à letra é reta aos meus olhos: a mesma expressão com que o livro se fecha — cada um fazia o que era reto aos seus olhos. Sansão é o espelho de um Israel que faz o que quer."},
{v:4,t:"Seu pai e sua mãe não sabiam que isto vinha do Senhor, que buscava uma ocasião contra os filisteus; pois naquele tempo os filisteus dominavam sobre Israel.",n:"Deus escreve com as linhas tortas de Sansão: as suas paixões serão ocasião de libertação para Israel."},
{v:5,t:"Sansão desceu com seu pai e sua mãe a Tamna. Quando chegaram às vinhas de Tamna, eis que um leão novo veio rugindo ao seu encontro.",np:1},
{v:6,t:"O Espírito do Senhor apoderou-se de Sansão, e ele despedaçou o leão como se despedaça um cabrito, sem ter nada na mão; mas não contou a seu pai nem a sua mãe o que tinha feito."},
{v:7,t:"Desceu e falou à mulher, e ela agradou a Sansão."},
{v:8,t:"Alguns dias depois, voltou para casar-se com ela e desviou-se do caminho para ver o cadáver do leão: havia no corpo do leão um enxame de abelhas e mel.",n:"Tocar num cadáver era proibido ao nazireu. Sansão passa por cima da sua consagração, um passo de cada vez."},
{v:9,t:"Tirou o mel com as mãos e foi comendo pelo caminho; quando chegou a seu pai e a sua mãe, deu-lhes, e eles comeram; mas não lhes disse que tinha tirado o mel do corpo do leão."},
{v:10,t:"Seu pai desceu à casa da mulher, e Sansão ofereceu ali um banquete, como os jovens costumavam fazer.",np:1,n:"Banquete, à letra festa de bebida: difícil de imaginar sem vinho, outra proibição do nazireu."},
{v:11,t:"Quando o viram, escolheram trinta companheiros para ficarem com ele."},
{v:12,t:"Sansão disse-lhes: Vou propor-vos um enigma; se o decifrardes dentro dos sete dias do banquete e o acertardes, eu vos darei trinta túnicas de linho e trinta mudas de roupa;"},
{v:13,t:"mas, se não puderdes decifrá-lo, vós me dareis trinta túnicas de linho e trinta mudas de roupa. Eles responderam-lhe: Propõe o teu enigma, que o ouviremos."},
{v:14,l:["Ele lhes disse:","Do que come saiu comida,","e do forte saiu doçura.","Durante três dias, não conseguiram decifrar o enigma."]},
{v:15,t:"No quarto dia, disseram à mulher de Sansão: Seduz o teu marido para que nos revele o enigma; senão, queimaremos a ti e a casa de teu pai. Foi para nos despojar que nos convidastes?",n:"O hebraico diz no sétimo dia; a Nova Vulgata, com a versão grega, lê no quarto, o que concorda com os três dias do versículo anterior."},
{v:16,t:"A mulher de Sansão chorava junto dele e dizia: Tu me odeias e não me amas; propuseste um enigma aos filhos do meu povo e a mim não o explicaste. Ele respondeu-lhe: Nem a meu pai nem a minha mãe o expliquei, e havia de explicá-lo a ti?"},
{v:17,t:"Ela chorou junto dele durante os sete dias do banquete; e, no sétimo dia, ele o explicou, porque ela o importunava; e ela logo o explicou aos filhos do seu povo."},
{v:18,l:["No sétimo dia, antes do pôr do sol, os homens da cidade disseram-lhe:","Que há mais doce que o mel?","E que há mais forte que o leão?","Ele respondeu-lhes:","Se não tivésseis lavrado com a minha novilha,","não teríeis decifrado o meu enigma."],n:"Lavrar com a novilha alheia: usar sem direito o que é de outro. A imagem é grosseira, como a situação."},
{v:19,t:"Então o Espírito do Senhor apoderou-se dele; desceu a Ascalon, matou ali trinta homens, tomou os seus despojos e deu as mudas de roupa aos que tinham decifrado o enigma; e, ardendo de ira, subiu à casa de seu pai.",np:1,n:"Ascalon ficava a uns quarenta quilômetros. O Espírito que vem sobre Sansão dá-lhe força, e não sabedoria: a força de Deus nas mãos de um homem sem freio."},
{v:20,t:"E a mulher de Sansão foi dada ao companheiro que lhe servira de padrinho."}
];

window.TEXTOS_SEED["juizes"][15] = [
{s:"As raposas e as searas dos filisteus"},
{v:1,t:"Algum tempo depois, no tempo da colheita do trigo, Sansão foi visitar a sua mulher, levando-lhe um cabrito; e quis entrar no quarto dela. Mas o pai dela não o deixou entrar"},
{v:2,t:"e disse-lhe: Pensei que a odiavas, e a dei ao teu companheiro. A sua irmã mais nova não é mais bonita do que ela? Fica com ela em seu lugar."},
{v:3,t:"Sansão disse-lhes: Desta vez não terei culpa diante dos filisteus, se lhes fizer mal.",n:"Sansão age por vingança pessoal, e o livro não o esconde; mas os seus golpes enfraquecem o opressor de Israel."},
{v:4,t:"Sansão foi, apanhou trezentas raposas, tomou tochas, amarrou as raposas cauda com cauda e pôs uma tocha entre cada par de caudas.",n:"Raposas, ou chacais, que andam em bandos e são mais fáceis de apanhar."},
{v:5,t:"Acendeu as tochas e soltou as raposas nas searas dos filisteus; e queimou tanto os feixes como o trigo por colher, e até as vinhas e os olivais."},
{v:6,t:"Os filisteus perguntaram: Quem fez isto? Responderam: Foi Sansão, genro do tamnita, porque este lhe tomou a mulher e a deu ao companheiro. Os filisteus subiram e queimaram-na, a ela e ao pai dela.",n:"A ameaça que os filisteus fizeram à mulher no capítulo anterior cumpre-se, embora ela lhes tenha obedecido. A violência chama a violência."},
{v:7,t:"Sansão disse-lhes: Já que fazeis assim, não descansarei enquanto não me vingar de vós."},
{v:8,t:"E feriu-os com grande derrota, coxa e perna. Depois desceu e habitou na fenda do rochedo de Etam.",n:"Coxa e perna: expressão proverbial, de sentido incerto, para uma derrota completa."},
{s:"A queixada de jumento"},
{v:9,t:"Os filisteus subiram, acamparam em Judá e espalharam-se por Lequi.",np:1,n:"Lequi quer dizer queixada: o nome prepara o episódio."},
{v:10,t:"Os homens de Judá perguntaram-lhes: Por que subistes contra nós? Responderam: Subimos para prender Sansão e fazer-lhe o que ele nos fez."},
{v:11,t:"Três mil homens de Judá desceram à fenda do rochedo de Etam e disseram a Sansão: Não sabes que os filisteus dominam sobre nós? Que é isto que nos fizeste? Ele respondeu-lhes: O que eles me fizeram, isso lhes fiz eu.",n:"Judá prefere a submissão tranquila ao risco da liberdade: três mil homens vêm prender o único que resiste."},
{v:12,t:"Disseram-lhe: Descemos para te amarrar e te entregar nas mãos dos filisteus. Sansão disse-lhes: Jurai-me que vós mesmos não me matareis."},
{v:13,t:"Responderam-lhe: Não; só te amarraremos e te entregaremos nas mãos deles, mas não te mataremos. Amarraram-no com duas cordas novas e fizeram-no subir do rochedo."},
{v:14,t:"Quando ele chegou a Lequi, os filisteus vieram ao seu encontro com gritos de triunfo. Então o Espírito do Senhor apoderou-se dele, e as cordas que lhe prendiam os braços ficaram como fios de linho queimados pelo fogo, e as amarras caíram-lhe das mãos."},
{v:15,t:"Achou uma queixada de jumento ainda fresca, estendeu a mão, tomou-a e matou com ela mil homens",n:"Uma queixada ainda fresca, de um animal morto havia pouco: outro contato com cadáver."},
{v:16,l:["e disse:","Com a queixada de um jumento","fiz deles um montão!","Com a queixada de um jumento","matei mil homens!"],n:"Em hebraico, jumento e montão dizem-se com a mesma palavra, chamor: o cântico da vitória é um jogo de palavras."},
{v:17,t:"Quando acabou de falar, lançou fora a queixada; e deu àquele lugar o nome de Ramat-Lequi.",n:"Ramat-Lequi quer dizer a colina da queixada."},
{v:18,t:"Sansão teve muita sede e clamou ao Senhor, dizendo: Tu deste pela mão do teu servo esta grande salvação; e agora vou morrer de sede e cair nas mãos dos incircuncisos?",np:1,n:"É a primeira oração de Sansão: o herói da força descobre-se dependente de um pouco de água."},
{v:19,t:"Deus fendeu a cavidade que há em Lequi, e dela saiu água. Sansão bebeu, recobrou o ânimo e reviveu. Por isso deu àquela fonte o nome de En-Hacoré; ela está em Lequi até o dia de hoje.",n:"En-Hacoré quer dizer a fonte daquele que clama."},
{v:20,t:"Sansão julgou Israel, no tempo dos filisteus, durante vinte anos."}
];

window.TEXTOS_SEED["juizes"][16] = [
{s:"Sansão em Gaza"},
{v:1,t:"Sansão foi a Gaza, viu ali uma prostituta e entrou em casa dela."},
{v:2,t:"Disseram aos habitantes de Gaza: Sansão chegou aqui. Cercaram o lugar e ficaram à espreita dele toda a noite à porta da cidade; ficaram quietos durante toda a noite, dizendo: Ao amanhecer, nós o mataremos."},
{v:3,t:"Sansão dormiu até a meia-noite; à meia-noite levantou-se, agarrou as folhas da porta da cidade e os dois batentes, arrancou-os com a tranca, pô-los aos ombros e levou-os ao cume do monte que está defronte de Hebron.",n:"De Gaza a Hebron são uns sessenta quilômetros, e uma subida de quase mil metros: o relato tem proporções de lenda. O homem que carrega as portas da cidade inimiga ainda é livre; logo perderá tudo."},
{s:"Sansão e Dalila"},
{v:4,t:"Depois disso, Sansão amou uma mulher do vale de Sorec, que se chamava Dalila.",np:1,n:"É a única mulher de Sansão que tem nome, e a única de quem se diz que ele a amou. Não se diz que ela o amasse."},
{v:5,t:"Os príncipes dos filisteus foram ter com ela e disseram-lhe: Seduz Sansão e descobre de onde vem a sua grande força, e como poderemos dominá-lo e amarrá-lo para o subjugar; e cada um de nós te dará mil e cem siclos de prata.",n:"Cinco príncipes, cada um com mil e cem siclos: uma fortuna."},
{v:6,t:"Dalila disse a Sansão: Dize-me, por favor, de onde vem a tua grande força, e com que se deveria amarrar-te para te subjugar."},
{v:7,t:"Sansão respondeu-lhe: Se me amarrarem com sete cordas de nervos frescos, que ainda não tenham secado, ficarei fraco e serei como qualquer outro homem."},
{v:8,t:"Os príncipes dos filisteus trouxeram-lhe sete cordas de nervos frescos, que ainda não tinham secado, e ela o amarrou com elas,"},
{v:9,t:"tendo homens de emboscada no quarto. E disse-lhe: Os filisteus estão sobre ti, Sansão! Ele rompeu as cordas como se rompe um fio de estopa quando sente o fogo. E não se descobriu o segredo da sua força."},
{v:10,t:"Dalila disse a Sansão: Zombaste de mim e disseste-me mentiras. Dize-me agora, por favor, com que se deveria amarrar-te.",np:1},
{v:11,t:"Ele respondeu-lhe: Se me amarrarem bem com cordas novas, que nunca tenham sido usadas, ficarei fraco e serei como qualquer outro homem."},
{v:12,t:"Dalila tomou cordas novas, amarrou-o com elas e disse-lhe: Os filisteus estão sobre ti, Sansão! — os homens estavam de emboscada no quarto. Mas ele rompeu as cordas dos braços como se fossem um fio."},
{v:13,t:"Dalila disse a Sansão: Até agora zombaste de mim e disseste-me mentiras. Dize-me com que se deveria amarrar-te. Ele respondeu-lhe: Se teceres as sete tranças da minha cabeça com a urdidura do tear e as prenderes com a cavilha, ficarei fraco e serei como qualquer outro homem.",np:1},
{v:14,t:"Ela o fez dormir, teceu as sete tranças da sua cabeça com a urdidura, prendeu-as com a cavilha e disse-lhe: Os filisteus estão sobre ti, Sansão! Ele acordou e arrancou a cavilha do tear com a urdidura.",n:"O hebraico é aqui mais breve; a Nova Vulgata segue um texto mais completo, conservado na versão grega. Sansão aproxima-se do segredo: a terceira mentira já fala do cabelo."},
{v:15,t:"Ela lhe disse: Como podes dizer que me amas, se o teu coração não está comigo? Três vezes zombaste de mim e não me disseste de onde vem a tua grande força.",np:1},
{v:16,t:"E, como ela o importunava todos os dias com as suas palavras e o atormentava, ele ficou com a alma cansada até a morte;"},
{v:17,t:"e abriu-lhe todo o seu coração, dizendo: Navalha nunca passou pela minha cabeça, porque sou nazireu de Deus desde o ventre de minha mãe. Se me raparem, a minha força me deixará, ficarei fraco e serei como qualquer outro homem.",n:"A força de Sansão não está nos cabelos como num amuleto, mas na consagração a Deus, de que o cabelo era o sinal. Ao revelar o segredo, Sansão entrega o último traço do seu voto."},
{v:18,t:"Dalila viu que ele lhe tinha aberto todo o seu coração; mandou chamar os príncipes dos filisteus e disse-lhes: Subi desta vez, porque ele me abriu todo o seu coração. Os príncipes dos filisteus subiram, levando o dinheiro nas mãos."},
{v:19,t:"Ela o fez dormir sobre os seus joelhos, chamou um homem e mandou rapar-lhe as sete tranças da cabeça; e começou a subjugá-lo, e a sua força retirou-se dele."},
{v:20,t:"E disse: Os filisteus estão sobre ti, Sansão! Ele acordou do sono e pensou: Sairei como das outras vezes e me livrarei. Mas não sabia que o Senhor se tinha retirado dele.",n:"É a frase mais triste da história de Sansão: não sabia que o Senhor se tinha retirado dele. A perda de Deus pode não ser sentida no momento em que acontece."},
{v:21,t:"Os filisteus agarraram-no, furaram-lhe os olhos e levaram-no para Gaza; prenderam-no com duas correntes de bronze, e ele girava a mó na prisão.",n:"Girar a mó era trabalho de escravos e de animais. O homem que se deixava levar pelo que via — vi uma mulher, ela me agrada — perde os olhos."},
{v:22,t:"Mas o cabelo da sua cabeça começou a crescer, depois de rapado."},
{s:"A morte de Sansão"},
{v:23,l:["Os príncipes dos filisteus reuniram-se para oferecer um grande sacrifício a Dagon, seu deus, e para se alegrarem; e diziam:","O nosso deus entregou","nas nossas mãos","Sansão, o nosso inimigo."],n:"Dagon, deus dos cereais, era o grande deus dos filisteus. A disputa já não é entre Sansão e os filisteus, mas entre o Senhor e Dagon."},
{v:24,l:["O povo, vendo-o, louvava o seu deus e dizia:","O nosso deus entregou nas nossas mãos","o nosso inimigo,","o que devastava a nossa terra","e matou tantos dos nossos."]},
{v:25,t:"Quando estavam alegres, disseram: Chamai Sansão, para que nos divirta. Mandaram vir Sansão da prisão, e ele os divertia; e puseram-no de pé entre as colunas."},
{v:26,t:"Sansão disse ao jovem que o levava pela mão: Deixa-me tocar as colunas que sustentam o templo, para que eu me apoie nelas."},
{v:27,t:"O templo estava cheio de homens e mulheres; estavam ali todos os príncipes dos filisteus, e no terraço havia cerca de três mil homens e mulheres, que olhavam Sansão, que os divertia."},
{v:28,t:"Então Sansão invocou o Senhor, dizendo: Senhor Deus, lembra-te de mim! Dá-me força só mais esta vez, ó Deus, para que eu me vingue dos filisteus, ao menos por um dos meus dois olhos!",np:1,n:"É a segunda e última oração de Sansão. Ainda aqui fala de vingança; mas volta-se para Deus."},
{v:29,t:"E, agarrando as duas colunas do meio, sobre as quais o templo se apoiava, apoiou-se nelas, numa com a mão direita e na outra com a esquerda,"},
{v:30,t:"e disse: Morra eu com os filisteus! Empurrou com força, e o templo caiu sobre os príncipes e sobre todo o povo que nele estava. E os que ele matou ao morrer foram mais do que os que matara em vida.",n:"Nota do tradutor: a morte de Sansão não é apresentada como um suicídio a imitar, e a Igreja nunca a leu assim; Santo Agostinho explica que Sansão agiu por impulso do Espírito que nele habitava, e não por desespero. O narrador vê nela o último ato de um libertador que se entrega com o inimigo. A Carta aos Hebreus nomeia Sansão entre os homens de fé."},
{v:31,t:"Seus irmãos e toda a família de seu pai desceram, tomaram-no e levaram-no para sepultá-lo entre Saraá e Estaol, no sepulcro de Manué, seu pai. Ele julgara Israel durante vinte anos.",np:1}
];

window.TEXTOS_SEED["juizes"][17] = [
{s:"O ídolo de Micas"},
{v:1,t:"Havia um homem da montanha de Efraim chamado Micas,",n:"Os capítulos 17 a 21 formam um apêndice, fora da sequência dos juízes: dois episódios que mostram a desordem religiosa e moral de um Israel sem rei. O refrão que os enquadra é: naqueles dias não havia rei em Israel. Micas, Mikayehu, quer dizer quem é como o Senhor? — nome irônico para o homem que fabrica um ídolo."},
{v:2,t:"que disse a sua mãe: Os mil e cem siclos de prata que te foram tirados, e a respeito dos quais proferiste uma maldição, que eu mesmo ouvi, estão comigo: fui eu que os tirei. Sua mãe disse: Bendito seja o meu filho pelo Senhor!",n:"O filho devolve o dinheiro por medo da maldição da mãe, e ela a anula com uma bênção. A religião da família é feita de fórmulas mágicas."},
{v:3,t:"Ele devolveu os mil e cem siclos de prata a sua mãe, e ela disse: Consagro de minha mão esta prata ao Senhor, em favor do meu filho, para fazer uma imagem esculpida e uma imagem de metal fundido. Agora, pois, eu a entrego a ti."},
{v:4,t:"Mas ele devolveu a prata a sua mãe; e a mãe tomou duzentos siclos e deu-os ao ourives, que fez com eles uma imagem esculpida e uma imagem de metal fundido; e ficaram na casa de Micas.",n:"Consagrados ao Senhor, mil e cem siclos; gastos na imagem, duzentos. E uma imagem do Senhor era proibida pelo mandamento do Sinai."},
{v:5,t:"Esse homem, Micas, tinha uma casa de Deus; fez um efod e terafins, e investiu um de seus filhos, que se tornou o seu sacerdote.",n:"Os terafins eram ídolos domésticos, como os que Raquel roubou a seu pai. Investir, à letra encher a mão, era a expressão técnica da ordenação sacerdotal."},
{v:6,t:"Naqueles dias não havia rei em Israel: cada um fazia o que lhe parecia reto.",n:"É o refrão do apêndice. Para o narrador, a desordem pede um rei; a história dos Reis mostrará que nem os reis bastam."},
{s:"O levita de Micas"},
{v:7,t:"Havia um jovem de Belém de Judá, do clã de Judá; era levita e residia ali como estrangeiro.",np:1},
{v:8,t:"Esse homem saiu da cidade de Belém de Judá para ir morar onde encontrasse lugar; e, seguindo o seu caminho, chegou à montanha de Efraim, à casa de Micas."},
{v:9,t:"Micas perguntou-lhe: De onde vens? Ele respondeu: Sou levita, de Belém de Judá, e vou morar onde encontrar lugar."},
{v:10,t:"Micas disse-lhe: Fica comigo e sê para mim pai e sacerdote; eu te darei dez siclos de prata por ano, a roupa e o sustento."},
{v:11,t:"O levita consentiu em ficar com aquele homem, e o jovem foi para ele como um dos seus filhos."},
{v:12,t:"Micas investiu o levita, e o jovem tornou-se o seu sacerdote e ficou na casa de Micas."},
{v:13,t:"E Micas disse: Agora sei que o Senhor me fará bem, porque tenho um levita como sacerdote.",n:"Micas pensa comprar a bênção de Deus com um sacerdote de boa família: a religião como garantia de prosperidade."}
];

window.TEXTOS_SEED["juizes"][18] = [
{s:"A migração de Dã"},
{v:1,t:"Naqueles dias não havia rei em Israel; e a tribo de Dã procurava para si um território onde habitar, pois até aquele dia não lhe tinha cabido herança no meio das tribos de Israel.",n:"O livro de Josué dizia que o território de Dã lhe escapou das mãos; aqui se conta como a tribo foi procurar outro."},
{v:2,t:"Os filhos de Dã enviaram, do seu clã, cinco homens valentes, de Saraá e de Estaol, para explorar e examinar a terra; e disseram-lhes: Ide, examinai a terra. Eles chegaram à montanha de Efraim, à casa de Micas, e ali pernoitaram."},
{v:3,t:"Estando perto da casa de Micas, reconheceram a voz do jovem levita; desviaram-se para lá e perguntaram-lhe: Quem te trouxe aqui? Que fazes aqui? Que tens aqui?",n:"Reconheceram a voz: talvez o sotaque do sul, ou a voz de alguém conhecido."},
{v:4,t:"Ele respondeu-lhes: Micas fez por mim isto e aquilo; contratou-me, e sou o seu sacerdote."},
{v:5,t:"Disseram-lhe: Consulta a Deus, para sabermos se a viagem que fazemos será bem-sucedida."},
{v:6,t:"O sacerdote respondeu-lhes: Ide em paz; o caminho que seguis está diante do Senhor."},
{v:7,t:"Os cinco homens partiram e chegaram a Lais; viram que o povo que ali habitava vivia em segurança, à maneira dos sidônios, tranquilo e confiante; não havia na terra quem os molestasse nem quem exercesse domínio; estavam longe dos sidônios e não tinham relações com a Síria.",np:1},
{v:8,t:"Voltaram a seus irmãos, em Saraá e Estaol, e os irmãos perguntaram-lhes: Que notícias trazeis?"},
{v:9,t:"Eles responderam: Levantai-vos e subamos contra eles, porque vimos a terra, e é muito boa. E vós ficais parados? Não sejais preguiçosos em ir tomar posse da terra."},
{v:10,t:"Quando lá chegardes, encontrareis um povo confiante, e a terra é espaçosa; Deus a entregou nas vossas mãos: é um lugar onde não falta nada do que há na terra."},
{v:11,t:"Partiram dali, do clã dos danitas, de Saraá e de Estaol, seiscentos homens armados para a guerra.",np:1},
{v:12,t:"Subiram e acamparam em Cariat-Iarim, em Judá; por isso aquele lugar se chama Maané-Dã até o dia de hoje; fica a oeste de Cariat-Iarim."},
{v:13,t:"Dali passaram à montanha de Efraim. Quando chegaram à casa de Micas,",np:1},
{v:14,t:"os cinco homens que tinham ido explorar a terra de Lais disseram a seus irmãos: Sabeis que nestas casas há um efod, terafins, uma imagem esculpida e uma imagem de metal fundido? Vede agora o que deveis fazer."},
{v:15,t:"Desviaram-se para lá, entraram na casa do jovem levita, na casa de Micas, e saudaram-no."},
{v:16,t:"Os seiscentos homens dos filhos de Dã, armados para a guerra, ficaram à entrada da porta."},
{v:17,t:"Os cinco homens que tinham ido explorar a terra entraram e tomaram a imagem esculpida, o efod, os terafins e a imagem de metal fundido, enquanto o sacerdote estava à entrada da porta com os seiscentos homens armados."},
{v:18,t:"Quando aqueles entraram na casa de Micas e tomaram a imagem esculpida, o efod, os terafins e a imagem de metal fundido, o sacerdote disse-lhes: Que fazeis?"},
{v:19,t:"Eles responderam-lhe: Cala-te, põe a mão sobre a boca e vem conosco, e sê para nós pai e sacerdote. Que é melhor para ti: ser sacerdote da casa de um só homem, ou ser sacerdote de uma tribo e de um clã em Israel?"},
{v:20,t:"O sacerdote alegrou-se; tomou o efod, os terafins e a imagem esculpida e foi no meio do povo.",n:"O levita troca de patrão sem escrúpulo, por um cargo melhor. O ídolo roubado será o santuário da tribo."},
{v:21,t:"Voltaram-se e partiram, pondo à frente as crianças, o gado e os bens.",np:1},
{v:22,t:"Já estavam longe da casa de Micas, quando os homens que moravam nas casas vizinhas da casa de Micas foram convocados e alcançaram os filhos de Dã."},
{v:23,t:"Gritaram atrás deles; e os filhos de Dã voltaram-se e disseram a Micas: Que queres? Por que vens com tanta gente?"},
{v:24,t:"Ele respondeu: Tomastes os deuses que eu fiz, e o sacerdote, e tudo o que tenho, e ainda me perguntais: Que tens?",n:"Os deuses que eu fiz: a frase condena-se a si mesma. Um deus que se pode roubar não salva ninguém."},
{v:25,t:"Os filhos de Dã disseram-lhe: Não nos faças ouvir mais a tua voz, para que não caiam sobre vós homens exasperados, e percas a tua vida com toda a tua casa."},
{v:26,t:"E os filhos de Dã seguiram o seu caminho. Micas, vendo que eram mais fortes do que ele, voltou-se e foi para sua casa."},
{v:27,t:"Eles tomaram o que Micas tinha feito e o sacerdote que ele tinha, e chegaram a Lais, a um povo tranquilo e confiante; passaram-no ao fio da espada e incendiaram a cidade.",np:1},
{v:28,t:"Não houve quem a socorresse, porque estava longe de Sidônia e não tinha relações com a Síria. Ficava no vale que pertence a Bet-Roob. Reconstruíram a cidade e habitaram nela,",n:"O narrador insiste na vítima: um povo pacífico e sem defesa. A conquista de Dã não tem nada de guerra santa."},
{v:29,t:"e deram à cidade o nome de Dã, do nome de Dã, seu pai, que nascera de Israel; mas antes a cidade chamava-se Lais."},
{v:30,t:"Os filhos de Dã ergueram para si a imagem esculpida; e Jônatas, filho de Gérson, filho de Moisés, e os seus filhos foram sacerdotes da tribo de Dã até o dia do exílio da terra.",n:"Neto de Moisés: o levita de Micas descendia do grande legislador. Os copistas judeus, para poupar a honra de Moisés, acrescentaram ao nome uma letra suspensa, e passou a ler-se Manassés; a Nova Vulgata lê Moisés. Dã será, com Betel, um dos dois santuários do reino do Norte, onde Jeroboão porá um bezerro de ouro."},
{v:31,t:"Assim, a imagem esculpida que Micas tinha feito ficou entre eles durante todo o tempo em que a casa de Deus esteve em Silo."}
];
